// 病句 코스 6 — tools/make_bingju.py 가 tools/bingju/c06.json 에서 만든다. 직접 고치지 않는다.
(window.BJ=window.BJ||{})[6]=[[{"o":["普洱茶属于后发酵茶，其独特的陈香源于长期存放过程中微生物对茶叶内含物质的缓慢转化。","冻土层中封存着大量远古时期的有机碳，一旦因气候变暖而加速融化，便可能释放出数量惊人的温室气体。","经过徽州茶商数十年间沿着水陆商路的长途贩运与苦心经营，使祁门红茶在十九世纪末便已享誉欧洲市场。","这位青年导演的处女作以一个西北小县城为背景，用近乎纪录片的冷静笔触，刻画了三代人迥然不同的人生选择。"],"a":2,"type":"주어 결여","why":"“经过……，使……” 때문에 “祁门红茶”가 “使”의 목적어가 되어 문장에 주어가 없다.","fix":"经过徽州茶商数十年间沿着水陆商路的长途贩运与苦心经营，祁门红茶在十九世纪末便已享誉欧洲市场。","words":[["祁门红茶","Qímén hóngchá","기문 홍차"],["贩运","fànyùn","실어다 팔다"],["享誉","xiǎngyù","명성을 떨치다"],["发酵","fājiào","발효하다"],["冻土","dòngtǔ","동토"],["处女作","chǔnǚzuò","데뷔작"],["迥然不同","jiǒng rán bù tóng","판이하다"]],"tr":["보이차는 후발효차에 속하며, 그 독특한 묵은 향은 오랜 보관 과정에서 미생물이 찻잎 속 성분을 서서히 변화시킨 데서 나온다.","동토층에는 먼 옛날의 유기 탄소가 대량으로 갇혀 있어, 기후 온난화로 녹는 속도가 빨라지면 엄청난 양의 온실가스가 방출될 수 있다.","휘저우 차 상인들이 수십 년 동안 물길과 육로를 따라 먼 거리를 실어 나르며 공들여 장사한 덕분에, 기문 홍차는 19세기 말에 이미 유럽 시장에서 명성을 떨쳤다.","이 젊은 감독의 데뷔작은 서북 지방의 작은 현성을 배경으로, 다큐멘터리에 가까운 냉정한 필치로 삼대의 판이한 인생 선택을 그려 냈다."],"ow":[[["普洱茶","pǔ'ěrchá","보이차"],["发酵","fājiào","발효"],["陈香","chénxiāng","묵은 향"],["微生物","wēishēngwù","미생물"],["转化","zhuǎnhuà","변화, 전환"]],[["冻土层","dòngtǔcéng","동토층"],["封存","fēngcún","봉인해 보관하다"],["有机碳","yǒujītàn","유기 탄소"],["温室气体","wēnshì qìtǐ","온실가스"],["释放","shìfàng","방출하다"]],[["徽州","Huīzhōu","휘주(지명)"],["贩运","fànyùn","실어다 팔다"],["苦心经营","kǔxīn jīngyíng","공들여 운영하다"],["祁门红茶","Qímén hóngchá","기문 홍차"],["享誉","xiǎngyù","명성을 떨치다"]],[["处女作","chǔnǚzuò","데뷔작"],["县城","xiànchéng","현청 소재지"],["笔触","bǐchù","필치"],["刻画","kèhuà","묘사하다"],["迥然不同","jiǒngrán bù tóng","판이하다"]]]},{"o":["鉴于近年来消费者对食品添加剂安全问题的普遍担忧，令越来越多的食品企业开始在包装上醒目地标注“零添加”字样。","宋代文人推崇的“点茶”，是将茶末置于盏中，注入沸水后用茶筅反复击拂，使茶汤表面泛起细密的白色泡沫。","蜂鸟是世界上体型最小的鸟类之一，为了维持极高的新陈代谢，它每天需要摄取相当于自身体重一半以上的花蜜。","这部长篇小说以一座江南小镇百年间的兴衰为线索，将家族恩怨与时代变迁巧妙地交织在一起。"],"a":0,"type":"주어 결여","why":"“鉴于……，令……” 때문에 “食品企业”가 “令”의 목적어가 되어 주어가 없다.","fix":"鉴于近年来消费者对食品添加剂安全问题的普遍担忧，越来越多的食品企业开始在包装上醒目地标注“零添加”字样。","words":[["鉴于","jiànyú","~을 감안하여"],["添加剂","tiānjiājì","첨가제"],["茶筅","cháxiǎn","차선(차 젓는 솔)"],["击拂","jīfú","휘저어 치다"],["蜂鸟","fēngniǎo","벌새"],["新陈代谢","xīn chén dài xiè","신진대사"],["恩怨","ēnyuàn","은원"]],"tr":["최근 식품첨가물 안전에 대한 소비자들의 걱정이 널리 퍼지자, 점점 더 많은 식품 기업이 포장에 '무첨가'라는 문구를 눈에 띄게 표시하기 시작했다.","송나라 문인들이 즐긴 '점다'는 찻가루를 찻잔에 넣고 끓는 물을 부은 뒤 다선으로 거듭 휘저어 찻물 표면에 하얀 거품이 촘촘히 일게 하는 것이다.","벌새는 세상에서 가장 작은 새 가운데 하나로, 매우 높은 신진대사를 유지하려고 매일 자기 몸무게의 절반이 넘는 꽃꿀을 먹어야 한다.","이 장편소설은 강남의 한 작은 마을이 백 년 동안 흥하고 쇠한 과정을 줄기로 삼아, 집안의 원한과 시대의 변화를 교묘하게 엮어 냈다."],"ow":[[["鉴于","jiànyú","~을 감안하여"],["添加剂","tiānjiājì","첨가물"],["醒目","xǐngmù","눈에 띄다"],["标注","biāozhù","표기하다"]],[["推崇","tuīchóng","높이 받들다"],["点茶","diǎnchá","점다(가루차 타기)"],["茶筅","cháxiǎn","다선(차솔)"],["击拂","jīfú","휘젓다"],["泡沫","pàomò","거품"]],[["蜂鸟","fēngniǎo","벌새"],["新陈代谢","xīnchén dàixiè","신진대사"],["摄取","shèqǔ","섭취하다"],["花蜜","huāmì","꽃꿀"]],[["兴衰","xīngshuāi","흥망성쇠"],["线索","xiànsuǒ","줄거리의 실마리"],["恩怨","ēnyuàn","은원"],["变迁","biànqiān","변천"],["交织","jiāozhī","뒤얽히다"]]]},{"o":["我国的饺子已有一千八百多年的历史，新疆阿斯塔那唐墓中曾出土过形状与今天几乎无异的饺子实物。","城市规划者逐渐意识到，一味拓宽道路并不能根治交通拥堵，反而可能吸引更多车辆涌入，形成恶性循环。","她在小说中借一个乡村教师的视角，冷峻而克制地书写了上世纪八十年代农村教育的困境与希望。","通过对上千名志愿者长达十年的饮食记录与健康数据的追踪分析，让研究人员发现，常吃发酵食品的人群患肠道疾病的比例明显偏低。"],"a":3,"type":"주어 결여","why":"“通过……，让……” 때문에 “研究人员”이 “让”의 목적어가 되어 주어가 없다.","fix":"通过对上千名志愿者长达十年的饮食记录与健康数据的追踪分析，研究人员发现，常吃发酵食品的人群患肠道疾病的比例明显偏低。","words":[["追踪","zhuīzōng","추적하다"],["阿斯塔那","Āsītǎnà","아스타나(고분군)"],["根治","gēnzhì","근본적으로 고치다"],["恶性循环","èxìng xúnhuán","악순환"],["冷峻","lěngjùn","냉정하고 엄하다"],["克制","kèzhì","절제하다"]],"tr":["우리나라 자오쯔(만두)는 1,800여 년의 역사를 지니며, 신장 아스타나의 당나라 무덤에서는 오늘날과 모양이 거의 같은 자오쯔 실물이 나온 적이 있다.","도시 계획가들은 도로를 넓히기만 해서는 교통 체증을 뿌리 뽑을 수 없고, 오히려 더 많은 차량을 끌어들여 악순환이 생길 수 있다는 것을 점차 깨닫게 되었다.","그녀는 소설에서 한 시골 교사의 눈을 빌려 1980년대 농촌 교육의 어려움과 희망을 냉철하고 절제된 필치로 그려 냈다.","천여 명의 자원봉사자를 대상으로 10년에 걸친 식사 기록과 건강 데이터를 추적 분석한 결과, 연구진은 발효 식품을 자주 먹는 사람들의 장 질환 발병 비율이 뚜렷이 낮다는 사실을 발견했다."],"ow":[[["饺子","jiǎozi","자오쯔(만두)"],["阿斯塔那","Āsītǎnà","아스타나(고분군)"],["唐墓","tángmù","당나라 무덤"],["无异","wúyì","다를 바 없다"],["实物","shíwù","실물"]],[["一味","yíwèi","무턱대고"],["拓宽","tuòkuān","넓히다"],["根治","gēnzhì","근본적으로 고치다"],["拥堵","yōngdǔ","체증"],["恶性循环","èxìng xúnhuán","악순환"]],[["视角","shìjiǎo","시각"],["冷峻","lěngjùn","냉철하다"],["克制","kèzhì","절제하다"],["困境","kùnjìng","곤경"]],[["志愿者","zhìyuànzhě","자원봉사자"],["追踪","zhuīzōng","추적하다"],["发酵","fājiào","발효"],["肠道","chángdào","장"],["偏低","piāndī","낮은 편이다"]]]},{"o":["在高原上烧水，水温远未达到一百摄氏度就会沸腾，因此用普通锅煮出来的米饭往往夹生。","自从明代后期辣椒经海路传入我国东南沿海以来，使原本以花椒、生姜调味的川菜在此后的数百年间逐渐形成了麻辣鲜香的独特风味。","这种新型环保餐盒以甘蔗渣为原料，废弃后在自然环境中三个月左右即可完全分解。","所谓“报复性熬夜”，指的是白天时间被工作占满的人宁可牺牲睡眠，也要在深夜“夺回”一点自由时间。"],"a":1,"type":"주어 결여","why":"“自从……以来，使……” 때문에 “川菜”가 “使”의 목적어가 되어 주어가 없다.","fix":"自从明代后期辣椒经海路传入我国东南沿海以来，原本以花椒、生姜调味的川菜在此后的数百年间逐渐形成了麻辣鲜香的独特风味。","words":[["辣椒","làjiāo","고추"],["花椒","huājiāo","산초"],["麻辣","málà","얼얼하고 맵다"],["沸腾","fèiténg","끓다"],["夹生","jiāshēng","설익다"],["甘蔗渣","gānzhezhā","사탕수수 찌꺼기"],["报复性","bàofùxìng","보복성의"]],"tr":["고원에서 물을 끓이면 물 온도가 100도에 한참 못 미쳐도 끓기 때문에, 보통 냄비로 지은 밥은 흔히 설익는다.","명나라 후기에 고추가 바닷길로 우리나라 동남 연해에 들어온 뒤로, 원래 화자오와 생강으로 맛을 내던 쓰촨 요리는 그 후 수백 년 동안 점차 얼얼하고 매우면서 신선하고 향긋한 독특한 맛을 갖추게 되었다.","이 새로운 친환경 도시락 용기는 사탕수수 찌꺼기를 원료로 하여, 버린 뒤 자연환경에서 석 달 정도면 완전히 분해된다.","이른바 '보복성 밤샘'이란 낮 시간을 일에 다 빼앗긴 사람들이 잠을 줄여서라도 깊은 밤에 조금이나마 자유 시간을 '되찾으려는' 것을 말한다."],"ow":[[["高原","gāoyuán","고원"],["沸腾","fèiténg","끓다"],["夹生","jiāshēng","설익다"]],[["辣椒","làjiāo","고추"],["沿海","yánhǎi","연해"],["花椒","huājiāo","화자오(산초)"],["川菜","chuāncài","쓰촨 요리"],["麻辣","málà","얼얼하고 맵다"]],[["环保","huánbǎo","친환경"],["甘蔗渣","gānzhezhā","사탕수수 찌꺼기"],["废弃","fèiqì","버리다"],["分解","fēnjiě","분해되다"]],[["所谓","suǒwèi","이른바"],["报复性","bàofùxìng","보복성"],["熬夜","áoyè","밤을 새우다"],["宁可","nìngkě","차라리"],["牺牲","xīshēng","희생하다"]]]},{"o":["相传神农氏为了辨别草木的药性，曾遍尝百草，一日之内竟遇七十种毒，这一传说折射出先民认识药物的艰辛历程。","这项历时五年的大型调查，对我国南北方居民在主食结构、烹饪方式和用盐量等方面存在的差异。","白居易的诗歌语言平易浅近，据说他每写成一首诗，都要先念给不识字的老妇人听，直到对方能听懂才定稿。","这座城市的旧城改造并没有采取大拆大建的方式，而是在保留原有街巷肌理的基础上进行微更新。"],"a":1,"type":"술어 결여","why":"“对……差异” 개사구만 있고 “进行了比较” 같은 술어가 없다.","fix":"这项历时五年的大型调查，对我国南北方居民在主食结构、烹饪方式和用盐量等方面存在的差异进行了系统的比较。","words":[["烹饪","pēngrèn","요리하다"],["神农氏","Shénnóng shì","신농씨"],["折射","zhéshè","반영하다"],["艰辛","jiānxīn","고생스럽다"],["平易浅近","píng yì qiǎn jìn","쉽고 평이하다"],["定稿","dìnggǎo","원고를 확정하다"],["肌理","jīlǐ","결, 짜임"]],"tr":["전설에 따르면 신농씨는 풀과 나무의 약성을 가리려고 온갖 풀을 맛보다가 하루에 일흔 가지 독을 만났다고 하는데, 이 전설은 옛사람들이 약을 알아 가는 과정이 얼마나 고되었는지를 보여 준다.","5년에 걸친 이 대규모 조사는 우리나라 남북 지역 주민들의 주식 구성, 조리 방식, 소금 섭취량 등에 존재하는 차이를 다루었다.","백거이의 시는 말이 쉽고 평이한데, 그는 시 한 수를 쓸 때마다 먼저 글을 모르는 할머니에게 읽어 주고 상대가 알아들을 때까지 고친 뒤에야 확정했다고 한다.","이 도시의 옛 시가지 개조는 크게 허물고 크게 짓는 방식을 쓰지 않고, 원래 골목의 결을 살린 바탕 위에서 작은 단위로 고쳐 나갔다."],"ow":[[["相传","xiāngchuán","전해지기로"],["神农氏","Shénnóng shì","신농씨"],["遍尝百草","biàn cháng bǎi cǎo","온갖 풀을 맛보다"],["折射","zhéshè","반영하다"],["先民","xiānmín","옛사람"]],[["历时","lìshí","시간이 걸리다"],["主食","zhǔshí","주식"],["烹饪","pēngrèn","요리하다"],["差异","chāyì","차이"]],[["白居易","Bái Jūyì","백거이"],["平易","píngyì","평이하다"],["浅近","qiǎnjìn","알기 쉽다"],["定稿","dìnggǎo","원고를 확정하다"]],[["大拆大建","dà chāi dà jiàn","대규모 철거·건설"],["街巷","jiēxiàng","골목"],["肌理","jīlǐ","결, 짜임"],["微更新","wēigēngxīn","소규모 재생"]]]},{"o":["古人将一夜分为五更，每更约两个小时，“三更半夜”指的便是午夜前后人们睡得最沉的时候。","随着冷冻干燥技术的成熟，冻干水果、方便汤料等食品在复水后几乎能够还原新鲜时的口感与香气。","这位科学家一生淡泊名利，他把获得的奖金悉数捐给了家乡的学校，自己却始终过着简朴的生活。","针对部分外卖平台上的商家使用劣质食材、后厨卫生状况堪忧等消费者反映强烈的问题，市场监管部门今年以来的多轮专项整治行动。"],"a":3,"type":"술어 결여","why":"“市场监管部门”이 주어인데 “今年以来的多轮专项整治行动”은 명사구일 뿐 “开展了” 같은 술어가 없다.","fix":"针对部分外卖平台上的商家使用劣质食材、后厨卫生状况堪忧等消费者反映强烈的问题，市场监管部门今年以来开展了多轮专项整治行动。","words":[["外卖","wàimài","배달 음식"],["劣质","lièzhì","질 낮은"],["堪忧","kānyōu","걱정스럽다"],["整治","zhěngzhì","단속하다"],["五更","wǔgēng","오경"],["淡泊名利","dàn bó míng lì","명리에 담담하다"],["悉数","xīshù","전부"]],"tr":["옛사람들은 하룻밤을 다섯 경으로 나누었는데 한 경은 약 두 시간이며, '삼경 한밤중'은 자정 무렵 사람들이 가장 깊이 잠든 때를 가리킨다.","동결 건조 기술이 성숙해지면서 동결 건조 과일, 즉석 수프 재료 같은 식품은 물에 불리면 신선할 때의 식감과 향을 거의 되살릴 수 있게 되었다.","이 과학자는 평생 명예와 이익에 담담하여 받은 상금을 모두 고향 학교에 기부하고, 자신은 늘 검소하게 살았다.","일부 배달 플랫폼 입점 업체의 저질 식재료 사용, 걱정스러운 주방 위생 등 소비자 불만이 큰 문제에 대해 시장감독 부서는 올해 들어 여러 차례 특별 단속을 벌였다."],"ow":[[["五更","wǔ gēng","오경"],["三更半夜","sān gēng bàn yè","한밤중"],["午夜","wǔyè","자정"]],[["冷冻干燥","lěngdòng gānzào","동결 건조"],["冻干","dònggān","동결 건조한"],["复水","fùshuǐ","물에 다시 불리다"],["还原","huányuán","되살리다"]],[["淡泊名利","dànbó míng lì","명리에 담담하다"],["悉数","xīshù","전부"],["简朴","jiǎnpǔ","검소하다"]],[["外卖","wàimài","배달 음식"],["劣质","lièzhì","저질"],["堪忧","kānyōu","우려스럽다"],["市场监管","shìchǎng jiānguǎn","시장 감독"],["专项整治","zhuānxiàng zhěngzhì","특별 정비"]]]},{"o":["为了让更多人了解中医药文化，这家已有百年历史的中药铺把药材的炮制、配伍和煎煮方法以图文并茂的形式。","腌制咸菜时加入的大量食盐能抑制细菌的繁殖，这正是古人在没有冰箱的年代长期保存蔬菜的智慧。","南极帝企鹅在零下四十多摄氏度的严寒中孵蛋，雄企鹅要不吃不喝地站立两个多月。","他在书中提出，真正的阅读不是被动地接受信息，而是与作者展开一场跨越时空的对话。"],"a":0,"type":"술어 결여","why":"“把……以……的形式” 뒤에 “展示在……” 같은 동사가 없어 “把” 구문이 끝나지 않았다.","fix":"为了让更多人了解中医药文化，这家已有百年历史的中药铺把药材的炮制、配伍和煎煮方法以图文并茂的形式展示在店堂的墙上。","words":[["炮制","páozhì","(약재를) 가공하다"],["配伍","pèiwǔ","(약재를) 배합하다"],["煎煮","jiānzhǔ","달이다"],["图文并茂","tú wén bìng mào","그림과 글이 모두 훌륭하다"],["腌制","yānzhì","절이다"],["孵蛋","fūdàn","알을 품다"]],"tr":["더 많은 사람이 중의약 문화를 알도록, 백 년 역사의 이 한약방은 약재의 법제·배합·달이는 방법을 그림과 글을 곁들인 형태로 소개했다.","짠지를 담글 때 넣는 많은 소금은 세균의 번식을 억제하는데, 이것이 바로 냉장고가 없던 시절 옛사람들이 채소를 오래 보관하던 지혜다.","남극의 황제펭귄은 영하 40도가 넘는 혹한 속에서 알을 품는데, 수컷은 두 달 넘게 먹지도 마시지도 않고 서 있어야 한다.","그는 책에서 진정한 독서는 정보를 수동적으로 받아들이는 것이 아니라 시공을 넘어 작가와 대화를 나누는 것이라고 주장했다."],"ow":[[["中医药","zhōngyīyào","중의약"],["炮制","páozhì","(약재를) 법제하다"],["配伍","pèiwǔ","약재 배합"],["煎煮","jiānzhǔ","달이다"],["图文并茂","tú wén bìng mào","그림과 글이 모두 훌륭하다"]],[["腌制","yānzhì","절이다"],["咸菜","xiáncài","짠지"],["抑制","yìzhì","억제하다"],["繁殖","fánzhí","번식"]],[["帝企鹅","dìqǐ'é","황제펭귄"],["严寒","yánhán","혹한"],["孵蛋","fūdàn","알을 품다"]],[["被动","bèidòng","수동적"],["跨越","kuàyuè","뛰어넘다"],["时空","shíkōng","시공"]]]},{"o":["相传豆腐是西汉淮南王刘安在炼丹时偶然制成的，此后历经两千余年，衍生出了千变万化的吃法。","设计者巧妙地借助两岸陡峭的岩壁作为支撑，使这座单拱石桥与周围的山势浑然一体，仿佛天然生成。","研究发现，睡前长时间盯着手机屏幕，屏幕发出的蓝光会抑制褪黑素的分泌，从而打乱人体原本稳定的。","在人口持续向大城市集聚的背景下，中小城市如何留住年轻人，成为地方政府亟须破解的课题。"],"a":2,"type":"목적어·중심어 결여","why":"“打乱人体原本稳定的” 뒤에 중심어 “昼夜节律”가 없다.","fix":"研究发现，睡前长时间盯着手机屏幕，屏幕发出的蓝光会抑制褪黑素的分泌，从而打乱人体原本稳定的昼夜节律。","words":[["褪黑素","tuìhēisù","멜라토닌"],["昼夜节律","zhòuyè jiélǜ","생체 리듬"],["淮南王","Huáinán wáng","회남왕"],["炼丹","liàndān","단약을 만들다"],["衍生","yǎnshēng","파생하다"],["浑然一体","hún rán yì tǐ","하나로 어우러지다"],["集聚","jíjù","모이다"]],"tr":["두부는 서한의 회남왕 유안이 연단을 하다가 우연히 만들었다고 전해지며, 그 뒤 2천여 년을 거치며 천변만화의 먹는 법이 생겨났다.","설계자는 양쪽 기슭의 가파른 암벽을 지지대로 교묘히 이용해, 이 단일 아치 돌다리가 주변 산세와 하나로 어우러져 마치 저절로 생겨난 듯 보이게 했다.","연구에 따르면 잠들기 전 휴대폰 화면을 오래 보면 화면의 블루라이트가 멜라토닌 분비를 억제해, 원래 안정되어 있던 인체의 생체 리듬을 흐트러뜨린다.","인구가 계속 대도시로 몰리는 상황에서, 중소 도시가 어떻게 젊은이를 붙잡을지는 지방 정부가 시급히 풀어야 할 과제가 되었다."],"ow":[[["相传","xiāngchuán","전해지기로"],["淮南王","Huáinán wáng","회남왕"],["刘安","Liú Ān","유안"],["炼丹","liàndān","연단하다"],["衍生","yǎnshēng","파생되다"],["千变万化","qiān biàn wàn huà","천변만화"]],[["陡峭","dǒuqiào","가파르다"],["岩壁","yánbì","암벽"],["单拱","dāngǒng","단일 아치"],["浑然一体","húnrán yì tǐ","혼연일체"]],[["蓝光","lánguāng","블루라이트"],["抑制","yìzhì","억제하다"],["褪黑素","tuìhēisù","멜라토닌"],["分泌","fēnmì","분비"]],[["集聚","jíjù","모이다"],["亟须","jíxū","시급히 ~해야 한다"],["破解","pòjiě","풀다, 해결하다"],["课题","kètí","과제"]]]},{"o":["江南不少地方在立夏这天有吃乌米饭的习俗，人们用南烛树叶的汁液浸泡糯米，蒸出的饭色泽乌黑发亮。","这位老匠人用了整整三年时间，才将这台锈迹斑斑的清代座钟修复如初，让它重新走动起来。","面对突发的公共卫生事件，及时、准确、公开地发布信息，是稳定公众情绪的重要前提。","这本由多位营养学家联合编写的科普读物，以通俗易懂的语言纠正了人们在日常饮食中长期存在的。"],"a":3,"type":"목적어·중심어 결여","why":"“纠正了……长期存在的” 뒤에 “误区” 같은 목적어가 없다.","fix":"这本由多位营养学家联合编写的科普读物，以通俗易懂的语言纠正了人们在日常饮食中长期存在的种种误区。","words":[["科普","kēpǔ","과학 대중화"],["误区","wùqū","잘못된 인식"],["乌米饭","wūmǐfàn","검은 찹쌀밥"],["糯米","nuòmǐ","찹쌀"],["锈迹斑斑","xiù jì bān bān","녹이 잔뜩 슬다"],["修复如初","xiū fù rú chū","원래대로 복원하다"]],"tr":["강남의 많은 지방에는 입하에 우미반을 먹는 풍습이 있는데, 남촉나무 잎의 즙에 찹쌀을 담갔다 찌면 밥이 새까맣게 윤이 난다.","이 노장인은 꼬박 3년을 들여서야 녹이 잔뜩 슨 청나라 탁상시계를 원래대로 고쳐 다시 움직이게 했다.","갑작스러운 공중보건 사건 앞에서 정보를 제때, 정확하게, 공개적으로 알리는 것은 대중의 정서를 안정시키는 중요한 전제다.","여러 영양학자가 함께 쓴 이 교양 과학책은 쉬운 말로 사람들이 일상의 식생활에서 오래 가져온 잘못된 생각을 바로잡았다."],"ow":[[["立夏","lìxià","입하"],["乌米饭","wūmǐfàn","우미반(검은 찹쌀밥)"],["南烛","nánzhú","남촉나무"],["糯米","nuòmǐ","찹쌀"],["浸泡","jìnpào","담그다"]],[["匠人","jiàngrén","장인"],["锈迹斑斑","xiù jì bān bān","녹이 얼룩덜룩하다"],["座钟","zuòzhōng","탁상시계"],["修复如初","xiūfù rú chū","원래대로 복원하다"]],[["突发","tūfā","돌발하다"],["公共卫生","gōnggòng wèishēng","공중보건"],["前提","qiántí","전제"]],[["营养学家","yíngyǎngxuéjiā","영양학자"],["科普读物","kēpǔ dúwù","교양 과학서"],["通俗易懂","tōngsú yì dǒng","쉽고 알기 쉽다"],["纠正","jiūzhèng","바로잡다"]]]},{"o":["人体的肠道中生活着数以万亿计的微生物，它们不仅参与食物的消化吸收，还与情绪调节密切相关。","近年来，这个以盛产高山云雾茶闻名的山区小县通过建设标准化茶园、引入电商直播，显著提高了当地茶农的。","这部话剧把古希腊悲剧的结构移植到当代都市生活中，探讨了个人意志与命运之间的永恒冲突。","成语“望梅止渴”出自曹操行军途中的一个故事，后来比喻用空想来安慰自己。"],"a":1,"type":"목적어·중심어 결여","why":"“提高了当地茶农的” 뒤에 “收入” 같은 중심어가 없다.","fix":"近年来，这个以盛产高山云雾茶闻名的山区小县通过建设标准化茶园、引入电商直播，显著提高了当地茶农的收入。","words":[["云雾茶","yúnwùchá","운무차"],["电商","diànshāng","전자상거래"],["直播","zhíbō","라이브 방송"],["数以万亿计","shù yǐ wàn yì jì","수조에 달하다"],["移植","yízhí","옮겨 심다"],["望梅止渴","wàng méi zhǐ kě","매실을 상상하며 갈증을 달래다"]],"tr":["사람의 장 속에는 수조 마리의 미생물이 사는데, 이들은 음식의 소화와 흡수에 관여할 뿐 아니라 감정 조절과도 밀접한 관계가 있다.","최근 고산 운무차로 이름난 이 산골 작은 현은 표준화 차밭을 조성하고 전자상거래 라이브 방송을 도입해 지역 차 농가의 소득을 크게 높였다.","이 연극은 고대 그리스 비극의 구조를 현대 도시 생활에 옮겨 와 개인의 의지와 운명 사이의 영원한 갈등을 탐구했다.","성어 '망매지갈'은 조조가 행군하던 중의 이야기에서 나왔으며, 뒤에 헛된 상상으로 스스로를 달래는 것을 비유하게 되었다."],"ow":[[["肠道","chángdào","장"],["数以万亿计","shù yǐ wàn yì jì","수조에 이르다"],["微生物","wēishēngwù","미생물"],["消化吸收","xiāohuà xīshōu","소화·흡수"]],[["盛产","shèngchǎn","많이 나다"],["云雾茶","yúnwùchá","운무차"],["标准化","biāozhǔnhuà","표준화"],["电商直播","diànshāng zhíbō","전자상거래 라이브 방송"],["茶农","chánóng","차 농가"]],[["话剧","huàjù","연극"],["悲剧","bēijù","비극"],["移植","yízhí","옮겨 심다"],["探讨","tàntǎo","탐구하다"],["永恒","yǒnghéng","영원하다"]],[["成语","chéngyǔ","성어"],["望梅止渴","wàng méi zhǐ kě","매실을 생각하며 갈증을 달래다"],["曹操","Cáo Cāo","조조"],["行军","xíngjūn","행군하다"],["比喻","bǐyù","비유하다"]]]}],[{"o":["据测算，一棵树龄在百年以上的老茶树，每年春季可采摘的鲜叶大约只有三到五斤左右，因此其制成的茶叶售价往往十分昂贵。","清代袁枚在《随园食单》中，不仅记录了三百多种南北菜肴的做法，还提出了“戒耳餐”“戒目食”等颇有见地的饮食主张。","地质学家在这块距今约三亿年的岩层中，发现了保存极为完整的远古蜻蜓化石，其翼展竟接近七十厘米。","许多人误以为失眠只是精神紧张造成的小毛病，殊不知长期失眠还会诱发一系列躯体疾病。"],"a":0,"type":"어림수 중복","why":"“大约”와 “左右”가 둘 다 어림을 나타내 겹친다(“三到五斤”도 이미 범위다).","fix":"据测算，一棵树龄在百年以上的老茶树，每年春季可采摘的鲜叶只有三到五斤，因此其制成的茶叶售价往往十分昂贵。","words":[["鲜叶","xiānyè","생찻잎"],["袁枚","Yuán Méi","원매(청대 문인)"],["随园食单","Suíyuán Shídān","수원식단"],["见地","jiàndì","식견"],["翼展","yìzhǎn","날개 길이"],["殊不知","shūbùzhī","뜻밖에도 ~을 모르다"],["诱发","yòufā","유발하다"]],"tr":["추산에 따르면 수령 백 년이 넘는 늙은 차나무 한 그루에서 해마다 봄에 딸 수 있는 생잎은 대략 3~5근 정도뿐이어서, 그것으로 만든 차는 흔히 값이 매우 비싸다.","청나라 원매는 『수원식단』에서 남북 요리 300여 가지의 조리법을 기록했을 뿐 아니라 '귀로 먹지 말라', '눈으로 먹지 말라' 같은 꽤 식견 있는 음식관도 내놓았다.","지질학자들은 약 3억 년 전의 이 암석층에서 보존 상태가 매우 완전한 고대 잠자리 화석을 발견했는데, 날개 길이가 70센티미터에 가까웠다.","많은 사람이 불면증을 정신적 긴장 때문에 생기는 사소한 병으로 잘못 아는데, 오랜 불면이 여러 신체 질환을 부를 수 있다는 것은 모른다."],"ow":[[["测算","cèsuàn","추산하다"],["树龄","shùlíng","수령"],["采摘","cǎizhāi","따다"],["鲜叶","xiānyè","생잎"],["昂贵","ángguì","비싸다"]],[["袁枚","Yuán Méi","원매"],["随园食单","Suíyuán Shídān","수원식단"],["菜肴","càiyáo","요리"],["颇有见地","pō yǒu jiàndì","꽤 식견이 있다"]],[["地质学家","dìzhìxuéjiā","지질학자"],["岩层","yáncéng","암석층"],["蜻蜓","qīngtíng","잠자리"],["化石","huàshí","화석"],["翼展","yìzhǎn","날개 폭"]],[["误以为","wù yǐwéi","잘못 여기다"],["殊不知","shūbùzhī","뜻밖에도 모르다"],["诱发","yòufā","유발하다"],["躯体","qūtǐ","신체"]]]},{"o":["在没有温度计的古代，酿酒师傅全凭手感和嗅觉来判断发酵的程度，这种经验往往需要十几年才能练就。","极地科考队员在漫长的极夜中容易出现失眠、情绪低落等症状，因此科考站会利用模拟日光的灯具帮助他们调节作息。","这座图书馆的外立面由上千块可旋转的铝板组成，能够随着日照角度的变化自动调节室内的光线。","这家始创于清代道光年间的酱园，至今仍沿用传统工艺，一缸黄豆酱从下料到出缸，前后要经历近一年多的日晒夜露。"],"a":3,"type":"어림수 중복","why":"“近”(조금 못 미침)과 “多”(넘음)가 함께 쓰여 겹치고 모순된다.","fix":"这家始创于清代道光年间的酱园，至今仍沿用传统工艺，一缸黄豆酱从下料到出缸，前后要经历一年多的日晒夜露。","words":[["酱园","jiàngyuán","장 공방"],["道光","Dàoguāng","도광(청 연호)"],["日晒夜露","rì shài yè lù","낮엔 볕, 밤엔 이슬을 맞다"],["酿酒","niàngjiǔ","술을 빚다"],["嗅觉","xiùjué","후각"],["练就","liànjiù","단련해 익히다"],["极夜","jíyè","극야"],["作息","zuòxī","일과 휴식"]],"tr":["온도계가 없던 옛날에는 술 빚는 장인이 오로지 손의 감각과 후각으로 발효 정도를 판단했는데, 이런 경험은 흔히 십여 년이 걸려야 익힐 수 있었다.","극지 탐사대원은 긴 극야 속에서 불면, 우울감 같은 증상을 겪기 쉬워, 기지에서는 햇빛을 흉내 낸 조명으로 생활 리듬을 조절하도록 돕는다.","이 도서관의 외벽은 회전하는 알루미늄판 천여 장으로 되어 있어 햇빛 각도에 따라 실내 빛을 자동으로 조절한다.","청나라 도광 연간에 문을 연 이 장 공방은 지금도 전통 공법을 쓰는데, 콩된장 한 독을 담가 꺼내기까지 1년 남짓 햇볕과 밤이슬을 맞힌다."],"ow":[[["温度计","wēndùjì","온도계"],["酿酒","niàngjiǔ","술을 빚다"],["嗅觉","xiùjué","후각"],["发酵","fājiào","발효"],["练就","liànjiù","익혀 몸에 붙이다"]],[["科考","kēkǎo","과학 탐사"],["极夜","jíyè","극야"],["失眠","shīmián","불면"],["模拟","mónǐ","모방하다"],["作息","zuòxī","생활 리듬"]],[["外立面","wàilìmiàn","건물 외벽"],["旋转","xuánzhuǎn","회전하다"],["铝板","lǚbǎn","알루미늄판"],["日照","rìzhào","일조"]],[["道光","Dàoguāng","도광(연호)"],["酱园","jiàngyuán","장 공방"],["沿用","yányòng","그대로 쓰다"],["黄豆酱","huángdòujiàng","콩된장"],["日晒夜露","rì shài yè lù","낮엔 볕, 밤엔 이슬을 맞히다"]]]},{"o":["牛奶中的乳糖需要在乳糖酶的作用下才能被分解吸收，而许多成年人体内乳糖酶的活性较低，喝牛奶后便容易腹胀。","这位年逾古稀的老药工从十几岁起便在药房当学徒，一生都在毕生致力于中药饮片的切制与鉴别。","南宋时期，临安城的夜市往往通宵达旦，即使在寒冬腊月，街头的饮食摊贩也照常营业。","唐代出现的曲辕犁把直辕改为曲辕，犁身更加轻巧灵活，便于在狭小的水田中回转耕作。"],"a":1,"type":"단어 안의 뜻 반복","why":"“毕生”이 이미 ‘평생’이라는 뜻이라 “一生”과 겹친다.","fix":"这位年逾古稀的老药工从十几岁起便在药房当学徒，毕生致力于中药饮片的切制与鉴别。","words":[["年逾古稀","nián yú gǔ xī","일흔이 넘다"],["毕生","bìshēng","평생"],["饮片","yǐnpiàn","탕제용 약재 조각"],["乳糖酶","rǔtángméi","락타아제"],["腹胀","fùzhàng","배가 더부룩하다"],["临安","Lín'ān","임안(남송 수도)"],["通宵达旦","tōng xiāo dá dàn","밤새도록"],["曲辕犁","qūyuánlí","곡원려(굽은 끌채 쟁기)"]],"tr":["우유의 젖당은 락타아제가 있어야 분해되어 흡수되는데, 많은 성인은 몸속 락타아제 활성이 낮아 우유를 마시면 배가 더부룩해지기 쉽다.","일흔이 넘은 이 늙은 약공은 십 대부터 약방에서 도제로 일하며 평생 한약 음편을 썰고 감별하는 일에 힘을 쏟았다.","남송 시대 임안성의 야시장은 흔히 밤새 열렸고, 한겨울에도 거리의 음식 노점은 평소처럼 장사를 했다.","당나라 때 나온 곡원리는 곧은 쟁기 자루를 굽은 자루로 바꿔 쟁기가 더 가볍고 다루기 쉬워져 좁은 논에서 방향을 돌리며 갈기에 편했다."],"ow":[[["乳糖","rǔtáng","젖당"],["乳糖酶","rǔtángméi","락타아제"],["分解","fēnjiě","분해하다"],["活性","huóxìng","활성"],["腹胀","fùzhàng","복부 팽만"]],[["年逾古稀","nián yú gǔxī","나이가 일흔을 넘다"],["学徒","xuétú","도제"],["毕生","bìshēng","평생"],["致力于","zhìlì yú","힘을 쏟다"],["饮片","yǐnpiàn","음편(썬 약재)"],["鉴别","jiànbié","감별하다"]],[["临安","Lín'ān","임안(남송 수도)"],["通宵达旦","tōngxiāo dá dàn","밤을 새워 아침까지"],["寒冬腊月","hán dōng là yuè","엄동설한"],["摊贩","tānfàn","노점상"]],[["曲辕犁","qūyuánlí","곡원리(굽은 쟁기)"],["轻巧","qīngqiǎo","가볍고 날렵하다"],["灵活","línghuó","유연하다"],["耕作","gēngzuò","경작하다"]]]},{"o":["古人认为“冬不藏精，春必病温”，因此主张冬季应早睡晚起，以顺应自然界闭藏的规律。","火星表面的平均气温只有零下六十摄氏度左右，大气中二氧化碳的含量高达百分之九十五。","这种产自岭南的陈皮，存放年份越久，其所含的挥发油成分转化得越充分，香气也就变得愈加更醇厚。","这家企业把员工的心理健康纳入了管理体系，定期邀请专业咨询师为员工提供免费的心理疏导。"],"a":2,"type":"단어 안의 뜻 반복","why":"“愈加”와 “更”가 둘 다 ‘더욱’이라는 뜻이라 겹친다.","fix":"这种产自岭南的陈皮，存放年份越久，其所含的挥发油成分转化得越充分，香气也就变得愈加醇厚。","words":[["岭南","Lǐngnán","영남(광둥 일대)"],["陈皮","chénpí","진피(묵은 귤껍질)"],["挥发油","huīfāyóu","휘발성 기름"],["醇厚","chúnhòu","진하고 그윽하다"],["闭藏","bìcáng","닫아 갈무리하다"],["疏导","shūdǎo","(마음을) 풀어 주다"]],"tr":["옛사람들은 '겨울에 정기를 갈무리하지 않으면 봄에 반드시 열병을 앓는다'고 여겨, 겨울에는 일찍 자고 늦게 일어나 자연이 닫고 감추는 이치를 따라야 한다고 했다.","화성 표면의 평균 기온은 영하 60도 안팎에 불과하고, 대기 중 이산화탄소 함량은 95퍼센트에 이른다.","영남 지방에서 나는 이 진피는 오래 묵을수록 그 속의 휘발성 기름 성분이 충분히 변해 향도 더욱 진해진다.","이 기업은 직원의 정신 건강을 관리 체계에 넣고, 정기적으로 전문 상담사를 불러 직원에게 무료 심리 상담을 제공한다."],"ow":[[["藏精","cáng jīng","정기를 갈무리하다"],["病温","bìng wēn","열병을 앓다"],["顺应","shùnyìng","순응하다"],["闭藏","bìcáng","닫고 감추다"]],[["火星","huǒxīng","화성"],["二氧化碳","èryǎnghuàtàn","이산화탄소"],["含量","hánliàng","함량"]],[["岭南","Lǐngnán","영남(광둥 일대)"],["陈皮","chénpí","진피(말린 귤껍질)"],["挥发油","huīfāyóu","휘발성 기름"],["醇厚","chúnhòu","깊고 진하다"]],[["纳入","nàrù","포함시키다"],["咨询师","zīxúnshī","상담사"],["疏导","shūdǎo","풀어 주다"]]]},{"o":["所谓“药食同源”，是指许多食物既能充饥果腹，又具有一定的药用价值，山药、红枣、枸杞便是其中的代表。","考古人员在一处新石器时代遗址中发现了炭化的粟粒，这表明当时的先民已经开始种植小米。","为鼓励市民养成健康的饮食习惯，社区卫生服务中心每月为辖区居民免费提供营养咨询，不收取任何费用。","她坚持用胶片相机记录老城区即将消失的街景，几年下来积累了上万张珍贵的影像资料。"],"a":2,"type":"단어 안의 뜻 반복","why":"“免费”가 곧 ‘돈을 받지 않는다’는 뜻이라 “不收取任何费用”이 겹친다.","fix":"为鼓励市民养成健康的饮食习惯，社区卫生服务中心每月为辖区居民免费提供营养咨询。","words":[["辖区","xiáqū","관할 구역"],["药食同源","yào shí tóng yuán","약과 음식은 뿌리가 같다"],["充饥果腹","chōng jī guǒ fù","허기를 채우다"],["枸杞","gǒuqǐ","구기자"],["炭化","tànhuà","탄화하다"],["粟","sù","조"],["胶片","jiāopiàn","필름"]],"tr":["이른바 '약식동원'이란 많은 음식이 배를 채울 수 있을 뿐 아니라 약효도 어느 정도 있다는 뜻으로, 마, 대추, 구기자가 그 대표이다.","고고학자들은 한 신석기 유적에서 탄화된 조 알갱이를 발견했는데, 이는 당시 사람들이 이미 조를 심기 시작했음을 보여 준다.","시민들의 건강한 식습관을 장려하려고, 지역 보건소는 매달 관내 주민에게 무료로 영양 상담을 제공하며 어떤 비용도 받지 않는다.","그녀는 곧 사라질 구시가지 거리 풍경을 필름 카메라로 꾸준히 기록해, 몇 년 동안 만 장이 넘는 귀중한 사진 자료를 모았다."],"ow":[[["药食同源","yào shí tóng yuán","약과 음식은 근원이 같다"],["充饥果腹","chōngjī guǒfù","배를 채우다"],["山药","shānyao","마"],["枸杞","gǒuqǐ","구기자"]],[["新石器时代","xīnshíqì shídài","신석기 시대"],["遗址","yízhǐ","유적"],["炭化","tànhuà","탄화하다"],["粟粒","sùlì","조 알갱이"]],[["社区","shèqū","지역 사회"],["辖区","xiáqū","관할 구역"],["营养咨询","yíngyǎng zīxún","영양 상담"],["收取","shōuqǔ","받다"]],[["胶片","jiāopiàn","필름"],["街景","jiējǐng","거리 풍경"],["影像","yǐngxiàng","영상, 사진"]]]},{"o":["在异国他乡的一家小店里，第一口尝到地道的桂林米粉时，离乡二十多年的老华侨不禁忍不住红了眼眶。","人体在深度睡眠阶段会分泌大量生长激素，这对儿童的骨骼发育和成年人的组织修复都十分关键。","这种生活在深海热泉附近的管状蠕虫没有消化系统，完全依靠体内共生的细菌来获取养分。","这次修订后的条例明确规定，景区门票价格的调整必须提前向社会公示，并广泛听取公众的意见。"],"a":0,"type":"단어 안의 뜻 반복","why":"“不禁”과 “忍不住”가 같은 뜻(저도 모르게)이라 겹친다.","fix":"在异国他乡的一家小店里，第一口尝到地道的桂林米粉时，离乡二十多年的老华侨不禁红了眼眶。","words":[["异国他乡","yì guó tā xiāng","이국 타향"],["地道","dìdao","본고장의"],["华侨","huáqiáo","화교"],["不禁","bùjīn","저도 모르게"],["生长激素","shēngzhǎng jīsù","성장 호르몬"],["热泉","rèquán","열수구"],["共生","gòngshēng","공생하다"],["公示","gōngshì","공시하다"]],"tr":["이국땅의 작은 가게에서 정통 구이린 쌀국수를 처음 한 입 맛보았을 때, 고향을 떠난 지 20여 년 된 노화교는 저도 모르게 눈시울이 붉어졌다.","사람은 깊은 잠 단계에서 성장호르몬을 많이 분비하는데, 이는 어린이의 뼈 발달과 성인의 조직 회복에 모두 매우 중요하다.","심해 열수구 근처에 사는 이 관벌레는 소화계가 없어 오로지 몸속에 공생하는 세균으로부터 양분을 얻는다.","이번에 개정된 조례는 관광지 입장료를 조정하려면 반드시 미리 사회에 공시하고 대중의 의견을 널리 들어야 한다고 분명히 규정했다."],"ow":[[["异国他乡","yì guó tā xiāng","이국 타향"],["地道","dìdao","정통의"],["米粉","mǐfěn","쌀국수"],["华侨","huáqiáo","화교"],["不禁","bùjīn","저도 모르게"],["眼眶","yǎnkuàng","눈시울"]],[["生长激素","shēngzhǎng jīsù","성장호르몬"],["骨骼","gǔgé","뼈"],["组织","zǔzhī","(신체) 조직"],["修复","xiūfù","회복하다"]],[["热泉","rèquán","열수구"],["蠕虫","rúchóng","벌레, 연충"],["消化系统","xiāohuà xìtǒng","소화계"],["共生","gòngshēng","공생하다"],["养分","yǎngfèn","양분"]],[["修订","xiūdìng","개정하다"],["条例","tiáolì","조례"],["公示","gōngshì","공시하다"],["听取","tīngqǔ","청취하다"]]]},{"o":["长时间保持低头看手机的姿势，颈椎承受的压力相当于平时的数倍，久而久之便可能引发颈椎病。","湖南的湘绣以针法多变、色彩丰富著称，所绣的狮虎毛发根根分明，几可乱真。","气象卫星能够连续监测台风的生成和移动路径，为沿海地区提前做好防御工作争取了宝贵时间。","山西人素有“一面百样吃”的本事，他们用小麦、莜麦、荞麦等杂粮，他们能做出刀削面、猫耳朵等数百种面食。"],"a":3,"type":"기타 군더더기(주어 반복)","why":"같은 문장 안에서 주어 “他们”을 두 번 썼다.","fix":"山西人素有“一面百样吃”的本事，他们用小麦、莜麦、荞麦等杂粮，能做出刀削面、猫耳朵等数百种面食。","words":[["莜麦","yóumài","쌀귀리"],["荞麦","qiáomài","메밀"],["刀削面","dāoxiāomiàn","도삭면"],["颈椎","jǐngzhuī","경추"],["湘绣","xiāngxiù","후난 자수"],["几可乱真","jī kě luàn zhēn","진짜와 거의 구별이 안 되다"]],"tr":["고개를 숙이고 휴대폰을 보는 자세를 오래 유지하면 목뼈가 받는 압력이 평소의 몇 배가 되어, 시간이 지나면 경추병이 생길 수 있다.","후난의 샹슈는 다채로운 자수법과 풍부한 색으로 이름났으며, 수놓은 사자와 호랑이의 털은 한 올 한 올 또렷해 진짜와 헷갈릴 정도다.","기상위성은 태풍의 발생과 이동 경로를 계속 감시할 수 있어, 연해 지역이 미리 방어 준비를 할 귀중한 시간을 벌어 준다.","산시 사람들은 '국수 하나로 백 가지를 먹는' 재주가 있어, 밀, 귀리, 메밀 같은 잡곡으로 도삭면, 마오얼둬 등 수백 가지 면 요리를 만들어 낸다."],"ow":[[["颈椎","jǐngzhuī","경추"],["久而久之","jiǔ ér jiǔ zhī","오랜 시간이 지나면"],["引发","yǐnfā","일으키다"]],[["湘绣","xiāngxiù","상수(후난 자수)"],["针法","zhēnfǎ","자수 기법"],["著称","zhùchēng","이름나다"],["几可乱真","jī kě luàn zhēn","진짜와 거의 구별이 안 되다"]],[["气象卫星","qìxiàng wèixīng","기상위성"],["监测","jiāncè","감시 측정하다"],["台风","táifēng","태풍"],["防御","fángyù","방어"]],[["素有","sùyǒu","예로부터 지니다"],["莜麦","yóumài","쌀귀리"],["荞麦","qiáomài","메밀"],["刀削面","dāoxiāomiàn","도삭면"],["猫耳朵","māo'ěrduo","마오얼둬(조개 모양 면)"]]]},{"o":["在全球粮食供应链日益紧张的背景下，提高耕地的单位面积产量比单纯扩大种植面积更具可持续性。","这是我国科研人员首次在野外发现这种此前被认为已经绝迹的野生大茶树种群，这还是第一次。","这位纪录片导演花了整整四年时间跟拍一个藏族牧民家庭的转场生活，真实记录了他们随季节迁移的游牧传统。","瑜伽和太极虽然起源于不同的文化，但都强调呼吸与动作的协调，以及身心的整体平衡。"],"a":1,"type":"기타 군더더기","why":"앞에서 이미 “首次”라고 했는데 뒤에 “这还是第一次”를 또 붙여 같은 말을 되풀이했다.","fix":"这是我国科研人员首次在野外发现这种此前被认为已经绝迹的野生大茶树种群。","words":[["绝迹","juéjì","자취를 감추다"],["种群","zhǒngqún","개체군"],["供应链","gōngyìngliàn","공급망"],["可持续性","kěchíxùxìng","지속 가능성"],["转场","zhuǎnchǎng","목초지를 옮기다"],["游牧","yóumù","유목"]],"tr":["세계 식량 공급망이 갈수록 빠듯해지는 가운데, 경지의 단위 면적당 생산량을 높이는 것이 재배 면적을 넓히기만 하는 것보다 더 지속 가능하다.","이는 우리나라 연구진이 그동안 사라진 것으로 여겨졌던 이 야생 큰 차나무 군락을 야외에서 처음 발견한 것이다.","이 다큐멘터리 감독은 꼬박 4년 동안 한 티베트 유목민 가족의 목초지 이동 생활을 따라다니며, 계절 따라 옮겨 다니는 유목 전통을 사실대로 기록했다.","요가와 태극권은 서로 다른 문화에서 생겨났지만, 둘 다 호흡과 동작의 조화, 몸과 마음의 전체적인 균형을 중시한다."],"ow":[[["供应链","gōngyìngliàn","공급망"],["耕地","gēngdì","경지"],["单位面积","dānwèi miànjī","단위 면적"],["可持续性","kěchíxùxìng","지속 가능성"]],[["科研","kēyán","과학 연구"],["绝迹","juéjì","자취가 끊기다"],["种群","zhǒngqún","개체군"]],[["纪录片","jìlùpiàn","다큐멘터리"],["跟拍","gēnpāi","따라다니며 찍다"],["牧民","mùmín","유목민"],["转场","zhuǎnchǎng","목초지를 옮기다"],["游牧","yóumù","유목"]],[["瑜伽","yújiā","요가"],["太极","tàijí","태극권"],["协调","xiétiáo","조화"],["身心","shēnxīn","몸과 마음"]]]},{"o":["凡是到过潮汕地区的游客，大都会对当地以牛肉丸和砂锅粥为代表的街头小吃留下深刻的印象。","珠江三角洲的桑基鱼塘以桑叶养蚕、蚕沙喂鱼、塘泥肥桑，形成了一个循环利用的生态农业系统。","唐代宫廷流行打马球，陕西出土的章怀太子墓壁画就生动描绘了贵族们策马击球的场景。","牦牛能适应海拔四五千米的高寒草场，其奶、肉、毛和粪便都能被牧民充分利用，因此被誉为“高原之舟”。"],"a":0,"type":"기타(凡是 호응)","why":"“凡是”는 ‘예외 없이 모두’라서 ‘대부분’을 뜻하는 “大都”와 맞지 않는다. “都”를 써야 한다.","fix":"凡是到过潮汕地区的游客，都会对当地以牛肉丸和砂锅粥为代表的街头小吃留下深刻的印象。","words":[["潮汕","Cháoshàn","차오산 지역"],["砂锅粥","shāguōzhōu","뚝배기 죽"],["马球","mǎqiú","폴로"],["章怀太子","Zhānghuái tàizǐ","장회태자"],["策马","cèmǎ","말을 몰다"],["桑基鱼塘","sāngjī yútáng","뽕나무 둑 양어장"],["蚕沙","cánshā","누에똥"],["牦牛","máoniú","야크"]],"tr":["차오산 지역에 가 본 여행객은 모두 소고기 완자와 뚝배기 죽으로 대표되는 그곳 길거리 음식에 깊은 인상을 받는다.","주장 삼각주의 상기어당은 뽕잎으로 누에를 치고, 누에똥을 물고기에게 먹이고, 연못 진흙으로 뽕나무에 거름을 주어 순환하며 이용하는 생태 농업 체계를 이룬다.","당나라 궁정에서는 격구가 유행했는데, 산시에서 출토된 장회태자 무덤 벽화에는 귀족들이 말을 달리며 공을 치는 장면이 생생하게 그려져 있다.","야크는 해발 4~5천 미터의 고한 초원에 적응할 수 있고, 젖·고기·털·똥까지 모두 유목민이 알뜰히 쓸 수 있어 '고원의 배'라고 불린다."],"ow":[[["凡是","fánshì","무릇 ~이면 모두"],["潮汕","Cháoshàn","차오산"],["牛肉丸","niúròuwán","소고기 완자"],["砂锅粥","shāguōzhōu","뚝배기 죽"]],[["珠江三角洲","Zhūjiāng Sānjiǎozhōu","주장 삼각주"],["桑基鱼塘","sāng jī yú táng","상기어당"],["蚕沙","cánshā","누에똥"],["塘泥","tángní","연못 진흙"]],[["宫廷","gōngtíng","궁정"],["马球","mǎqiú","격구(폴로)"],["章怀太子","Zhānghuái tàizǐ","장회태자"],["壁画","bìhuà","벽화"],["策马","cèmǎ","말을 몰다"]],[["牦牛","máoniú","야크"],["海拔","hǎibá","해발"],["高寒","gāohán","높고 추운"],["誉为","yùwéi","~라 불리다"]]]},{"o":["宇航员在太空中长期处于失重状态，骨骼中的钙质会不断流失，因此返回地面后需要较长时间的康复训练。","这位作曲家将江南丝竹的旋律融入交响乐之中，使东西方两种音乐语言实现了和谐的对话。","许多南方人冬天之所以爱喝羊肉汤，主要是因为羊肉性温，能够驱寒暖身的缘故。","在快递包装中过度使用胶带和泡沫填充物，不仅造成资源浪费，也给垃圾处理带来了沉重负担。"],"a":2,"type":"기타 군더더기","why":"“是因为”가 이미 이유를 말하는데 끝에 “的缘故”를 또 붙여 겹친다.","fix":"许多南方人冬天之所以爱喝羊肉汤，主要是因为羊肉性温，能够驱寒暖身。","words":[["驱寒","qūhán","추위를 쫓다"],["失重","shīzhòng","무중력"],["钙质","gàizhì","칼슘"],["康复","kāngfù","회복하다"],["丝竹","sīzhú","현악기와 관악기(전통 음악)"],["交响乐","jiāoxiǎngyuè","교향악"]],"tr":["우주인은 우주에서 오래 무중력 상태에 있으면 뼈의 칼슘이 계속 빠져나가, 지구로 돌아온 뒤 비교적 오랜 재활 훈련이 필요하다.","이 작곡가는 강남사죽의 선율을 교향악에 녹여 동서양 두 음악 언어가 조화롭게 대화하도록 했다.","많은 남방 사람이 겨울에 양고기탕을 즐기는 것은 주로 양고기가 성질이 따뜻해 추위를 몰아내고 몸을 데워 주기 때문이다.","택배 포장에 테이프와 스티로폼 충전재를 지나치게 쓰면 자원이 낭비될 뿐 아니라 쓰레기 처리에도 큰 부담이 된다."],"ow":[[["宇航员","yǔhángyuán","우주비행사"],["失重","shīzhòng","무중력"],["骨骼","gǔgé","뼈"],["钙质","gàizhì","칼슘"],["康复","kāngfù","재활"]],[["作曲家","zuòqǔjiā","작곡가"],["江南丝竹","Jiāngnán sīzhú","강남사죽"],["旋律","xuánlǜ","선율"],["交响乐","jiāoxiǎngyuè","교향악"]],[["性温","xìng wēn","성질이 따뜻하다"],["驱寒","qūhán","추위를 쫓다"],["缘故","yuángù","까닭"]],[["胶带","jiāodài","테이프"],["泡沫","pàomò","스티로폼"],["填充物","tiánchōngwù","충전재"],["沉重","chénzhòng","무겁다"]]]}],[{"o":["铁观音属于半发酵茶，冲泡后的叶片呈“绿叶红镶边”，香气馥郁持久，素有“七泡有余香”之誉。","近年来，各地通过开设社区营养课堂、发放膳食指南手册等方式，大力普及了居民的健康饮食水平。","长期伏案工作的人，不妨每隔一小时起身活动几分钟，以缓解肩颈部位的肌肉紧张。","这座海滨城市在填海造地的过程中，破坏了大片红树林湿地，导致近海渔业资源急剧减少。"],"a":1,"type":"동사–목적어","why":"“普及”는 “水平”과 어울리지 않는다. 보급하는 것은 “知识”다.","fix":"近年来，各地通过开设社区营养课堂、发放膳食指南手册等方式，大力普及了健康饮食知识。","words":[["普及","pǔjí","보급하다"],["铁观音","tiěguānyīn","철관음"],["镶边","xiāngbiān","테두리"],["馥郁","fùyù","향기가 짙다"],["伏案","fú'àn","책상에 엎드리다"],["填海造地","tián hǎi zào dì","바다를 메워 땅을 만들다"],["红树林","hóngshùlín","맹그로브 숲"]],"tr":["철관음은 반발효차로, 우린 뒤 잎은 '초록 잎에 붉은 테두리'를 띠고 향이 진하고 오래가 '일곱 번 우려도 향이 남는다'는 평을 듣는다.","최근 각지에서는 지역 영양 교실을 열고 식생활 지침 책자를 나눠 주는 방식으로 주민들의 건강한 식생활 수준을 크게 끌어올렸다.","오래 책상에 앉아 일하는 사람은 한 시간마다 일어나 몇 분간 몸을 움직여 어깨와 목 근육의 긴장을 풀어 주는 것이 좋다.","이 해안 도시는 바다를 메워 땅을 만드는 과정에서 넓은 맹그로브 습지를 파괴해 근해 어업 자원이 급격히 줄었다."],"ow":[[["铁观音","tiěguānyīn","철관음"],["冲泡","chōngpào","우리다"],["镶边","xiāngbiān","테두리를 두르다"],["馥郁","fùyù","향기가 짙다"],["素有","sùyǒu","예로부터 지니다"]],[["社区","shèqū","지역 사회"],["膳食","shànshí","식사"],["指南","zhǐnán","지침"],["普及","pǔjí","보급하다"]],[["伏案","fú'àn","책상에 엎드리다"],["不妨","bùfáng","~해도 좋다"],["缓解","huǎnjiě","완화하다"],["肩颈","jiānjǐng","어깨와 목"]],[["填海造地","tián hǎi zào dì","바다를 메워 땅을 만들다"],["红树林","hóngshùlín","맹그로브 숲"],["湿地","shīdì","습지"],["渔业","yúyè","어업"],["急剧","jíjù","급격하다"]]]},{"o":["这位年轻设计师把传统竹编技艺与现代家居设计相结合，让古老的手艺焕发出新的生机。","水母没有大脑和心脏，身体的百分之九十五以上都是水，却已在海洋中生存了五亿多年。","为了满足高海拔地区水的沸点偏低、食物难以煮熟的问题，当地居民普遍使用高压锅烹煮饭菜。","专家建议，晚餐不宜吃得过饱，最好在睡前三小时左右完成进食，以免影响睡眠质量。"],"a":2,"type":"동사–목적어","why":"满足는 需要·要求 같은 말과 어울리고 问题(문제)와는 어울리지 않는다. 问题는 解决와 짝을 이룬다.","fix":"为了解决高海拔地区水的沸点偏低、食物难以煮熟的问题，当地居民普遍使用高压锅烹煮饭菜。","words":[["沸点","fèidiǎn","끓는점"],["高压锅","gāoyāguō","압력솥"],["竹编","zhúbiān","대나무 공예"],["焕发","huànfā","발산하다"],["生机","shēngjī","생기"],["水母","shuǐmǔ","해파리"]],"tr":["이 젊은 디자이너는 전통 대나무 공예를 현대 가구 디자인과 결합해 오래된 솜씨에 새로운 활력을 불어넣었다.","해파리는 뇌와 심장이 없고 몸의 95퍼센트 이상이 물인데도, 바다에서 이미 5억 년 넘게 살아왔다.","고지대에서 물의 끓는점이 낮아 음식이 잘 익지 않는 문제를 해결하려고, 그곳 주민들은 압력솥으로 밥과 반찬을 짓는 경우가 많다.","전문가들은 저녁을 너무 배부르게 먹지 말고, 잠들기 세 시간쯤 전에 식사를 마쳐야 수면의 질에 영향을 주지 않는다고 권한다."],"ow":[[["竹编","zhúbiān","대나무 공예"],["技艺","jìyì","기예"],["焕发","huànfā","빛을 발하다"],["生机","shēngjī","활력"]],[["水母","shuǐmǔ","해파리"],["心脏","xīnzàng","심장"],["生存","shēngcún","생존하다"]],[["海拔","hǎibá","해발"],["沸点","fèidiǎn","끓는점"],["高压锅","gāoyāguō","압력솥"],["烹煮","pēngzhǔ","삶고 익히다"]],[["不宜","bùyí","~하는 것은 좋지 않다"],["进食","jìnshí","식사하다"],["以免","yǐmiǎn","~하지 않도록"]]]},{"o":["作为岭南饮食文化的重要组成部分，早茶在维系邻里感情、促进社会交往方面一直发扬着不可替代的作用。","蜜蜂酿造一公斤蜂蜜，需要往返采集数百万朵花，其飞行总里程相当于绕地球好几圈。","他在离开故乡半个世纪后重返旧地，发现儿时熟悉的小巷早已被高楼大厦所取代。","近年来，“轻断食”在年轻人中颇为流行，但医生提醒，患有低血糖或胃病的人不宜盲目尝试。"],"a":0,"type":"동사–목적어","why":"“作用”은 “发挥”와 어울린다. “发扬”은 “传统·精神”과 어울린다.","fix":"作为岭南饮食文化的重要组成部分，早茶在维系邻里感情、促进社会交往方面一直发挥着不可替代的作用。","words":[["早茶","zǎochá","아침 차(딤섬 문화)"],["维系","wéixì","유지하다"],["发扬","fāyáng","떨쳐 일으키다"],["酿造","niàngzào","양조하다"],["轻断食","qīngduànshí","간헐적 단식"],["低血糖","dīxuètáng","저혈당"]],"tr":["영남 음식 문화의 중요한 일부로서, 아침 차 문화는 이웃 간 정을 이어 주고 사회적 교류를 북돋는 데 줄곧 대신할 수 없는 역할을 해 왔다.","꿀벌이 꿀 1킬로그램을 만들려면 수백만 송이의 꽃을 오가며 모아야 하는데, 그 비행 거리는 지구를 몇 바퀴 도는 것과 맞먹는다.","그는 고향을 떠난 지 반세기 만에 옛 땅을 다시 찾았는데, 어린 시절 익숙했던 골목이 이미 고층 빌딩으로 바뀐 것을 알게 되었다.","최근 '간헐적 단식'이 젊은이들 사이에서 꽤 유행하지만, 의사들은 저혈당이나 위장병이 있는 사람은 함부로 시도하지 말라고 당부한다."],"ow":[[["岭南","Lǐngnán","영남(광둥 일대)"],["早茶","zǎochá","아침 차(딤섬)"],["维系","wéixì","유지하다"],["邻里","línlǐ","이웃"],["发扬","fāyáng","떨치다, 발양하다"]],[["蜜蜂","mìfēng","꿀벌"],["酿造","niàngzào","빚다, 만들다"],["采集","cǎijí","채집하다"],["里程","lǐchéng","거리"]],[["故乡","gùxiāng","고향"],["旧地","jiùdì","옛 땅"],["取代","qǔdài","대체하다"]],[["轻断食","qīng duànshí","간헐적 단식"],["颇为","pōwéi","꽤"],["低血糖","dīxuètáng","저혈당"],["盲目","mángmù","무턱대고"]]]},{"o":["宋代文人苏轼不仅诗词书画样样精通，还是一位美食家，相传东坡肉便是他在黄州时创制的。","人在受到惊吓时，肾上腺素会迅速分泌，使心跳加快、肌肉紧绷，以便随时应对危险。","这项研究首次证实，某些深海鱼类能够通过调节体内的特殊蛋白质，抵御海底巨大的水压。","这种以老面发酵、经柴火慢烤而成的锅盔，口感外脆里软，麦香浓郁，其价格一直深受当地人的喜爱。"],"a":3,"type":"주어–술어","why":"사랑받는 것은 빵(锅盔)이지 “价格”가 아니어서 “其价格……深受喜爱”는 주어와 술어가 맞지 않는다.","fix":"这种以老面发酵、经柴火慢烤而成的锅盔，口感外脆里软，麦香浓郁，一直深受当地人的喜爱。","words":[["老面","lǎomiàn","묵은 반죽(발효종)"],["柴火","cháihuo","장작"],["锅盔","guōkuī","꿔쿠이(큰 구운 빵)"],["东坡肉","dōngpōròu","동파육"],["黄州","Huángzhōu","황주"],["肾上腺素","shènshàngxiànsù","아드레날린"],["抵御","dǐyù","견디다"]],"tr":["송나라 문인 소식은 시·사·서예·그림에 두루 능했을 뿐 아니라 미식가이기도 해서, 동파육은 그가 황저우에 있을 때 만들었다고 전한다.","사람이 놀라면 아드레날린이 빠르게 분비되어 심장이 빨리 뛰고 근육이 굳어, 언제든 위험에 맞설 수 있게 된다.","이 연구는 일부 심해어가 몸속의 특수 단백질을 조절해 해저의 엄청난 수압을 견딜 수 있다는 것을 처음으로 입증했다.","묵은 반죽으로 발효해 장작불에 천천히 구운 이 궈쿠이는 겉은 바삭하고 속은 부드러우며 밀 향이 진해, 그 값이 늘 그곳 사람들에게 사랑받아 왔다."],"ow":[[["苏轼","Sū Shì","소식(소동파)"],["美食家","měishíjiā","미식가"],["东坡肉","dōngpōròu","동파육"],["黄州","Huángzhōu","황주"],["创制","chuàngzhì","창안하다"]],[["惊吓","jīngxià","놀라다"],["肾上腺素","shènshàngxiànsù","아드레날린"],["分泌","fēnmì","분비하다"],["紧绷","jǐnbēng","팽팽히 긴장하다"]],[["证实","zhèngshí","입증하다"],["蛋白质","dànbáizhì","단백질"],["抵御","dǐyù","막아 내다"],["水压","shuǐyā","수압"]],[["老面","lǎomiàn","묵은 반죽(발효종)"],["发酵","fājiào","발효"],["柴火","cháihuo","장작"],["锅盔","guōkuī","궈쿠이(구운 빵)"],["外脆里软","wài cuì lǐ ruǎn","겉은 바삭 속은 부드럽다"]]]},{"o":["四川泡菜讲究用老盐水浸泡，有些人家的泡菜坛子几十年不换，盐水越陈，泡出的菜就越香脆。","这座建于上世纪三十年代的老厂房经过改造，如今已成为一座集展览、演出和餐饮于一体的文化空间。","考古学家推测，这枚刻有符号的骨片可能是早期先民用来记录天数或猎物数量的工具。","由于工作压力大、作息不规律，许多都市年轻人的睡眠质量日益加重，失眠已成为困扰他们的常见问题。"],"a":3,"type":"주어–술어","why":"“质量”은 “加重”(심해지다)와 어울리지 않는다. 질은 “下降”한다.","fix":"由于工作压力大、作息不规律，许多都市年轻人的睡眠质量日益下降，失眠已成为困扰他们的常见问题。","words":[["泡菜","pàocài","파오차이(절임 채소)"],["坛子","tánzi","항아리"],["香脆","xiāngcuì","향긋하고 아삭하다"],["厂房","chǎngfáng","공장 건물"],["集…于一体","jí…yú yìtǐ","~을 한데 모으다"],["推测","tuīcè","추측하다"]],"tr":["쓰촨 파오차이는 묵은 소금물에 담그는 것을 중시해, 어떤 집은 파오차이 독을 수십 년 동안 바꾸지 않는데, 소금물이 묵을수록 절인 채소가 더 향긋하고 아삭하다.","1930년대에 지어진 이 옛 공장 건물은 개조를 거쳐 지금은 전시·공연·식음을 한데 모은 문화 공간이 되었다.","고고학자들은 부호가 새겨진 이 뼛조각이 초기 사람들이 날수나 사냥감 수를 기록하던 도구였을 것으로 추정한다.","업무 스트레스가 크고 생활이 불규칙해 많은 도시 젊은이의 수면의 질이 갈수록 나빠지고 있으며, 불면은 그들을 괴롭히는 흔한 문제가 되었다."],"ow":[[["泡菜","pàocài","파오차이(쓰촨 절임)"],["盐水","yánshuǐ","소금물"],["浸泡","jìnpào","담그다"],["坛子","tánzi","항아리"],["香脆","xiāngcuì","향긋하고 바삭하다"]],[["厂房","chǎngfáng","공장 건물"],["改造","gǎizào","개조하다"],["于一体","yú yìtǐ","하나로 합치다"]],[["考古学家","kǎogǔxuéjiā","고고학자"],["推测","tuīcè","추측하다"],["骨片","gǔpiàn","뼛조각"],["猎物","lièwù","사냥감"]],[["作息","zuòxī","생활 리듬"],["都市","dūshì","도시"],["失眠","shīmián","불면"],["困扰","kùnrǎo","괴롭히다"]]]},{"o":["用糯米、红豆、红枣、莲子等多种食材熬制而成的腊八粥，是我国北方许多地区在农历腊月初八这一天必不可少的节令。","长期摄入过量的反式脂肪酸，会升高血液中“坏胆固醇”的水平，增加患心脏病的风险。","这位登山家在没有携带氧气瓶的情况下成功登顶，创造了一项令业界瞩目的纪录。","城市里的流浪猫数量激增，不仅影响环境卫生，也对本地鸟类的生存构成了威胁。"],"a":0,"type":"주어–목적어","why":"주어는 음식 “腊八粥”인데 목적어가 절기 “节令”이라 “A是B”가 맞지 않는다.","fix":"用糯米、红豆、红枣、莲子等多种食材熬制而成的腊八粥，是我国北方许多地区在农历腊月初八这一天必不可少的节令食品。","words":[["莲子","liánzǐ","연밥"],["熬制","áozhì","고아 만들다"],["腊八粥","làbāzhōu","납팔죽"],["节令","jiélìng","절기"],["反式脂肪酸","fǎnshì zhīfángsuān","트랜스 지방산"],["瞩目","zhǔmù","주목하다"]],"tr":["찹쌀, 팥, 대추, 연밥 등 여러 재료로 끓인 납팔죽은 우리나라 북방 여러 지역에서 음력 섣달 초여드렛날에 빠질 수 없는 절기 음식이다.","트랜스지방산을 오래 지나치게 먹으면 혈중 '나쁜 콜레스테롤' 수치가 올라가 심장병 위험이 커진다.","이 산악인은 산소통 없이 정상에 올라 업계가 주목하는 기록을 세웠다.","도시의 길고양이 수가 급증하면서 환경 위생에 영향을 줄 뿐 아니라 토종 새들의 생존도 위협하고 있다."],"ow":[[["糯米","nuòmǐ","찹쌀"],["莲子","liánzǐ","연밥"],["熬制","áozhì","오래 끓이다"],["腊八粥","làbāzhōu","납팔죽"],["节令","jiélìng","절기"]],[["摄入","shèrù","섭취하다"],["反式脂肪酸","fǎnshì zhīfángsuān","트랜스지방산"],["胆固醇","dǎngùchún","콜레스테롤"]],[["登山家","dēngshānjiā","산악인"],["氧气瓶","yǎngqìpíng","산소통"],["登顶","dēngdǐng","정상에 오르다"],["瞩目","zhǔmù","주목하다"]],[["流浪猫","liúlàngmāo","길고양이"],["激增","jīzēng","급증하다"],["卫生","wèishēng","위생"],["构成","gòuchéng","이루다"],["威胁","wēixié","위협"]]]},{"o":["雷暴天气中产生的闪电能把空气中的氮气转化为氮的化合物，随雨水落入土壤，起到天然施肥的作用。","这家诞生于小作坊的品牌，凭借对品质的执着坚守，用二十年时间成长为行业的领军企业。","在这次国际美食节上，最受中外游客欢迎的，是来自西北的手抓羊肉和来自江南的蟹粉小笼包的摊位前。","心理学家指出，适当地向信任的人倾诉烦恼，可以有效减轻心理负担，避免负面情绪的积累。"],"a":2,"type":"주어–목적어","why":"주어 “最受欢迎的”는 음식인데 목적어가 장소 “摊位前”이라 맞지 않는다.","fix":"在这次国际美食节上，最受中外游客欢迎的，是来自西北的手抓羊肉和来自江南的蟹粉小笼包。","words":[["手抓羊肉","shǒuzhuā yángròu","손으로 뜯어 먹는 양고기"],["蟹粉","xièfěn","게살과 게장"],["雷暴","léibào","뇌우"],["化合物","huàhéwù","화합물"],["作坊","zuōfang","작업장"],["倾诉","qīngsù","털어놓다"]],"tr":["뇌우 때 생기는 번개는 공기 중의 질소를 질소 화합물로 바꿔, 빗물과 함께 흙에 떨어지게 해 천연 비료 역할을 한다.","작은 공방에서 시작한 이 브랜드는 품질에 대한 꾸준한 고집으로 20년 만에 업계 선두 기업으로 성장했다.","이번 국제 음식 축제에서 국내외 관광객에게 가장 인기 있었던 것은 서북 지방의 손으로 뜯어 먹는 양고기와 강남의 게살 샤오롱바오 노점이었다.","심리학자들은 믿을 만한 사람에게 고민을 적절히 털어놓으면 마음의 짐을 효과적으로 덜고 부정적 감정이 쌓이는 것을 막을 수 있다고 말한다."],"ow":[[["雷暴","léibào","뇌우"],["闪电","shǎndiàn","번개"],["氮气","dànqì","질소"],["化合物","huàhéwù","화합물"],["施肥","shīféi","비료를 주다"]],[["作坊","zuōfang","작업장"],["执着","zhízhuó","집착, 고집"],["坚守","jiānshǒu","굳게 지키다"],["领军","lǐngjūn","선두에 서다"]],[["美食节","měishíjié","음식 축제"],["手抓羊肉","shǒuzhuā yángròu","손으로 뜯어 먹는 양고기"],["蟹粉","xièfěn","게살"],["小笼包","xiǎolóngbāo","샤오롱바오"],["摊位","tānwèi","노점 자리"]],[["倾诉","qīngsù","털어놓다"],["烦恼","fánnǎo","고민"],["负面","fùmiàn","부정적"],["积累","jīlěi","쌓이다"]]]},{"o":["日本的寿司起源于古代东南亚一带用米饭发酵保存鱼类的方法，后来才逐渐演变为今天的生鱼寿司。","对于讲究本味的粤式清蒸鱼来说，鱼是否鲜活、蒸制的时间是否精准，直接决定了这道菜口感的鲜嫩爽滑。","人到中年以后，基础代谢率逐年下降，如果饮食习惯不随之调整，体重就很容易增加。","这家博物馆利用增强现实技术，让观众可以通过手机“看到”文物在千年前的原始色彩。"],"a":1,"type":"양면–한면","why":"앞은 “是否”(되나 안 되나) 두 면인데 뒤는 “鲜嫩爽滑” 한 면이라 맞지 않는다.","fix":"对于讲究本味的粤式清蒸鱼来说，鱼是否鲜活、蒸制的时间是否精准，直接决定了这道菜口感的好坏。","words":[["本味","běnwèi","본연의 맛"],["鲜活","xiānhuó","싱싱하게 살아 있다"],["蒸制","zhēngzhì","찌다"],["爽滑","shuǎnghuá","매끄럽다"],["寿司","shòusī","초밥"],["代谢率","dàixièlǜ","대사율"],["增强现实","zēngqiáng xiànshí","증강 현실"]],"tr":["일본 스시는 옛 동남아 일대에서 밥을 발효시켜 생선을 보존하던 방법에서 비롯되어, 뒤에 점차 오늘날의 생선회 스시로 변했다.","본연의 맛을 중시하는 광둥식 생선찜에서는 생선이 싱싱한지, 찌는 시간이 정확한지가 이 요리의 부드럽고 탱글한 식감을 직접 결정한다.","중년이 되면 기초대사율이 해마다 떨어져, 식습관을 그에 맞게 바꾸지 않으면 체중이 늘기 쉽다.","이 박물관은 증강현실 기술을 이용해 관람객이 휴대폰으로 천 년 전 유물의 본래 색깔을 '볼' 수 있게 했다."],"ow":[[["寿司","shòusī","스시"],["起源","qǐyuán","기원하다"],["发酵","fājiào","발효"],["演变","yǎnbiàn","변천하다"]],[["讲究","jiǎngjiu","중시하다"],["本味","běnwèi","본연의 맛"],["粤式","yuèshì","광둥식"],["清蒸","qīngzhēng","맑게 찌다"],["鲜活","xiānhuó","싱싱하다"],["爽滑","shuǎnghuá","매끄럽고 탱글하다"]],[["基础代谢率","jīchǔ dàixièlǜ","기초대사율"],["逐年","zhúnián","해마다"],["随之","suízhī","그에 따라"]],[["增强现实","zēngqiáng xiànshí","증강현실"],["文物","wénwù","문화재"],["原始","yuánshǐ","본래의"]]]},{"o":["徽州的臭鳜鱼闻起来有股特殊的气味，吃起来却鲜香无比，这种独特风味源于腌制过程中的轻度发酵。","在资讯高度碎片化的今天，能够静下心来读完一本厚书，已经成为一种难得的能力。","这条新开通的铁路穿越了多条地震断裂带，施工难度之大在世界铁路建设史上都极为罕见。","研究人员认为，晚上能否在固定的时间入睡并保证充足的睡眠时长，是青少年白天保持旺盛精力的重要条件。"],"a":3,"type":"양면–한면","why":"“能否”(두 면)와 “保持旺盛精力的条件”(한 면)이 맞지 않는다.","fix":"研究人员认为，晚上在固定的时间入睡并保证充足的睡眠时长，是青少年白天保持旺盛精力的重要条件。","words":[["旺盛","wàngshèng","왕성하다"],["徽州","Huīzhōu","휘주"],["臭鳜鱼","chòuguìyú","발효 쏘가리 요리"],["碎片化","suìpiànhuà","파편화"],["断裂带","duànlièdài","단층대"],["罕见","hǎnjiàn","드물다"]],"tr":["후이저우의 썩힌 쏘가리는 냄새가 독특하지만 먹어 보면 무척 신선하고 고소한데, 이 독특한 맛은 절이는 과정의 가벼운 발효에서 나온다.","정보가 지나치게 조각난 오늘날, 마음을 가라앉히고 두꺼운 책 한 권을 끝까지 읽는 것은 이미 드문 능력이 되었다.","새로 개통한 이 철도는 여러 지진 단층대를 지나가, 시공 난도가 세계 철도 건설사에서도 매우 드문 수준이다.","연구진은 밤에 정해진 시간에 잠들고 충분한 수면 시간을 지키는지가 청소년이 낮에 왕성한 기운을 유지하는 중요한 조건이라고 본다."],"ow":[[["徽州","Huīzhōu","휘주"],["臭鳜鱼","chòuguìyú","썩힌 쏘가리 요리"],["鲜香","xiānxiāng","신선하고 향긋하다"],["腌制","yānzhì","절이다"],["发酵","fājiào","발효"]],[["资讯","zīxùn","정보"],["碎片化","suìpiànhuà","파편화"],["难得","nándé","얻기 어렵다"]],[["开通","kāitōng","개통하다"],["穿越","chuānyuè","가로지르다"],["断裂带","duànlièdài","단층대"],["罕见","hǎnjiàn","드물다"]],[["入睡","rùshuì","잠들다"],["时长","shícháng","시간 길이"],["旺盛","wàngshèng","왕성하다"],["精力","jīnglì","기력"]]]},{"o":["在这场以非遗美食为主题的展销会上，游客们品尝到了各地风味独特的传统小吃和老师傅们高超的拉面技艺。","被称为“植物界大熊猫”的珙桐，是第四纪冰川期幸存下来的孑遗植物，其花朵形似展翅的白鸽。","这家养老院为每位老人建立了健康档案，并根据他们的身体状况量身定制一日三餐的食谱。","当人连续数日缺乏睡眠时，大脑处理情绪的能力会明显下降，人也会变得更容易急躁。"],"a":0,"type":"목적어 여럿 중 일부","why":"“品尝”은 “小吃”와는 맞지만 “拉面技艺”(솜씨)와는 맞지 않는다. 솜씨는 “欣赏”한다.","fix":"在这场以非遗美食为主题的展销会上，游客们品尝到了各地风味独特的传统小吃，还欣赏到了老师傅们高超的拉面技艺。","words":[["展销会","zhǎnxiāohuì","전시 판매회"],["风味","fēngwèi","풍미"],["珙桐","gǒngtóng","손수건나무"],["孑遗","jiéyí","살아남은"],["量身定制","liáng shēn dìng zhì","맞춤 제작하다"],["急躁","jízào","조급하다"]],"tr":["무형문화유산 음식을 주제로 한 이 전시 판매회에서 관광객들은 각지의 독특한 전통 간식을 맛보고 노장인들의 뛰어난 라몐 솜씨를 구경했다.","'식물계의 판다'라 불리는 손수건나무(궁퉁)는 제4기 빙하기에서 살아남은 잔존 식물로, 꽃 모양이 날개를 편 흰 비둘기 같다.","이 양로원은 노인마다 건강 기록을 만들고, 각자의 몸 상태에 맞춰 하루 세 끼 식단을 짜 준다.","며칠 동안 잠이 모자라면 뇌가 감정을 처리하는 능력이 눈에 띄게 떨어지고, 사람도 더 쉽게 조급해진다."],"ow":[[["非遗","fēiyí","무형문화유산"],["展销会","zhǎnxiāohuì","전시 판매회"],["风味","fēngwèi","풍미"],["拉面","lāmiàn","라몐(손으로 늘인 면)"],["技艺","jìyì","기예"]],[["珙桐","gǒngtóng","궁퉁(손수건나무)"],["第四纪","dì-sì jì","제4기"],["冰川期","bīngchuānqī","빙하기"],["孑遗植物","jiéyí zhíwù","잔존 식물"],["白鸽","báigē","흰 비둘기"]],[["养老院","yǎnglǎoyuàn","양로원"],["档案","dàng'àn","기록, 파일"],["量身定制","liàng shēn dìng zhì","맞춤 제작하다"],["食谱","shípǔ","식단"]],[["缺乏","quēfá","부족하다"],["急躁","jízào","조급하다"]]]}],[{"o":["中药方剂讲究“君臣佐使”，主药与辅药各司其职、相互配合，才能共同发挥治疗作用。","极地的冰芯中封存着数十万年前的空气气泡，为研究地球古气候提供了直接证据。","这家企业把废弃的咖啡渣加工成环保材料，制成的杯子和餐具既轻便又耐用。","等我们赶到这家以手工米粉闻名的小店时，当天限量供应的三百碗米粉卖已经光了。"],"a":3,"type":"부사·능원동사·부정사 위치","why":"부사 “已经”은 동사 “卖” 앞에 와야 한다. “卖已经光了”는 어순이 틀렸다.","fix":"等我们赶到这家以手工米粉闻名的小店时，当天限量供应的三百碗米粉已经卖光了。","words":[["米粉","mǐfěn","쌀국수"],["限量","xiànliàng","수량 한정"],["方剂","fāngjì","처방"],["君臣佐使","jūn chén zuǒ shǐ","군신좌사(약재 배합 원칙)"],["各司其职","gè sī qí zhí","각자 맡은 일을 하다"],["冰芯","bīngxīn","빙하 코어"]],"tr":["한약 처방은 '군신좌사'를 중시하는데, 주약과 보조약이 각자 맡은 일을 하며 서로 맞물려야 함께 치료 효과를 낼 수 있다.","극지의 빙하 코어에는 수십만 년 전의 공기 방울이 갇혀 있어, 지구 고기후 연구에 직접적인 증거를 제공한다.","이 기업은 버려진 커피 찌꺼기를 친환경 소재로 가공했는데, 그것으로 만든 컵과 식기는 가볍고 튼튼하다.","우리가 손으로 뽑은 쌀국수로 유명한 이 작은 가게에 도착했을 때, 그날 한정 판매하는 쌀국수 300그릇은 이미 다 팔렸다."],"ow":[[["方剂","fāngjì","처방"],["君臣佐使","jūn chén zuǒ shǐ","군신좌사"],["各司其职","gè sī qí zhí","각자 직분을 다하다"]],[["极地","jídì","극지"],["冰芯","bīngxīn","빙하 코어"],["封存","fēngcún","봉인하다"],["气泡","qìpào","기포"],["古气候","gǔqìhòu","고기후"]],[["废弃","fèiqì","버리다"],["咖啡渣","kāfēizhā","커피 찌꺼기"],["环保","huánbǎo","친환경"],["餐具","cānjù","식기"],["耐用","nàiyòng","오래 쓰다"]],[["米粉","mǐfěn","쌀국수"],["限量","xiànliàng","한정"],["供应","gōngyìng","공급하다"]]]},{"o":["芝麻经过炒制后再研磨成酱，香味会更加浓郁，这是因为高温促进了其中芳香物质的释放。","研究团队反复调整发酵温度和菌种配比，经过上百次试验，终于他们成功复原了这种失传已久的古法酱油。","这座城市在地铁站内设置了母婴室和无障碍通道，充分考虑了特殊人群的出行需求。","成语“脍炙人口”中的“脍”和“炙”原指切细的肉和烤肉，后来用以比喻好的诗文受到人们的称赞。"],"a":1,"type":"부사·능원동사·부정사 위치","why":"부사 “终于”는 주어 “他们” 뒤, 동사 앞에 와야 한다.","fix":"研究团队反复调整发酵温度和菌种配比，经过上百次试验，他们终于成功复原了这种失传已久的古法酱油。","words":[["菌种","jūnzhǒng","균종"],["配比","pèibǐ","배합 비율"],["酱油","jiàngyóu","간장"],["研磨","yánmó","갈다"],["无障碍","wúzhàng'ài","장애물 없는"],["脍炙人口","kuài zhì rén kǒu","사람들 입에 오르내리다"]],"tr":["참깨는 볶은 뒤 갈아 장으로 만들면 향이 더 진해지는데, 이는 높은 온도가 그 속 방향 물질의 방출을 촉진하기 때문이다.","연구팀은 발효 온도와 균주 배합을 거듭 조정하며 백 번 넘게 시험한 끝에, 오래전 맥이 끊긴 옛 방식의 간장을 마침내 되살리는 데 성공했다.","이 도시는 지하철역 안에 수유실과 무장애 통로를 설치해 교통 약자의 이동 요구를 충분히 배려했다.","성어 '회자인구'의 '회'와 '자'는 원래 잘게 썬 고기와 구운 고기를 뜻했는데, 뒤에 좋은 시문이 사람들에게 칭찬받는 것을 비유하게 되었다."],"ow":[[["芝麻","zhīma","참깨"],["研磨","yánmó","갈다"],["浓郁","nóngyù","짙다"],["芳香","fāngxiāng","향기"],["释放","shìfàng","방출"]],[["发酵","fājiào","발효"],["菌种","jūnzhǒng","균종"],["配比","pèibǐ","배합 비율"],["复原","fùyuán","복원하다"],["失传","shīchuán","전해지지 않게 되다"],["酱油","jiàngyóu","간장"]],[["母婴室","mǔyīngshì","수유실"],["无障碍","wúzhàng'ài","무장애"],["通道","tōngdào","통로"]],[["脍炙人口","kuài zhì rén kǒu","회자되다"],["比喻","bǐyù","비유하다"],["诗文","shīwén","시문"],["称赞","chēngzàn","칭찬하다"]]]},{"o":["人体大约每隔九十分钟会经历一次完整的睡眠周期，在一个周期结束时醒来，人往往会感觉更加清醒。","这种生长在高山流石滩上的雪莲，为了抵御严寒，全身长满了白色的绒毛。","这家百年老店做的叉烧肥瘦相间、甜咸适中，很卖得好，每天中午不到十二点就被抢购一空。","她把多年来在山区支教的经历写成了一本书，书中没有宏大的叙事，却处处流露出真挚的情感。"],"a":2,"type":"부사·능원동사·부정사 위치","why":"정도부사 “很”은 “得” 뒤 보어 앞에 와야 한다. “很卖得好”가 아니라 “卖得很好”다.","fix":"这家百年老店做的叉烧肥瘦相间、甜咸适中，卖得很好，每天中午不到十二点就被抢购一空。","words":[["叉烧","chāshāo","차슈"],["肥瘦相间","féi shòu xiāng jiàn","비계와 살코기가 섞이다"],["抢购一空","qiǎnggòu yìkōng","금세 다 팔리다"],["流石滩","liúshítān","너덜 지대"],["雪莲","xuělián","설련화"],["绒毛","róngmáo","솜털"],["支教","zhījiào","교육 봉사"]],"tr":["사람은 대략 90분마다 한 번의 완전한 수면 주기를 겪으며, 한 주기가 끝날 때 깨면 대개 더 개운하게 느낀다.","고산 너덜지대에 자라는 이 설련화는 혹한을 견디려고 온몸이 흰 솜털로 덮여 있다.","이 백 년 된 가게의 차샤오는 비계와 살코기가 섞여 있고 달고 짠맛이 알맞아 잘 팔려서, 매일 낮 열두 시도 되기 전에 다 팔려 나간다.","그녀는 여러 해 산골에서 봉사 교사로 일한 경험을 책으로 썼는데, 거창한 서사는 없지만 곳곳에 진솔한 감정이 배어 있다."],"ow":[[["周期","zhōuqī","주기"],["清醒","qīngxǐng","정신이 맑다"]],[["流石滩","liúshítān","너덜지대"],["雪莲","xuělián","설련화"],["抵御","dǐyù","막다"],["严寒","yánhán","혹한"],["绒毛","róngmáo","솜털"]],[["叉烧","chāshāo","차샤오(중국식 바비큐)"],["肥瘦相间","féi shòu xiāng jiàn","비계와 살이 섞이다"],["适中","shìzhōng","알맞다"],["抢购一空","qiǎnggòu yì kōng","다투어 사서 동나다"]],[["支教","zhījiào","교육 봉사"],["宏大","hóngdà","거대하다"],["叙事","xùshì","서사"],["流露","liúlù","드러나다"],["真挚","zhēnzhì","진지하다"]]]},{"o":["营养学家建议，烹饪绿叶蔬菜时应该先洗后切，并且尽量缩短加热时间，以减少维生素C的流失在烹饪过程中。","北魏贾思勰所著的《齐民要术》中，详细记载了制曲、酿酒、做酱等数十种农副产品的加工方法。","地铁早高峰期间，部分换乘站会采取限流措施，以确保乘客的安全和站内秩序。","那些整天抱怨没时间运动的人，其实只要每天少刷半小时手机，就能挤出锻炼的时间。"],"a":0,"type":"개사구 위치","why":"개사구 “在烹饪过程中”이 문장 끝에 떨어져 있다. “流失” 앞에 와서 꾸며야 한다.","fix":"营养学家建议，烹饪绿叶蔬菜时应该先洗后切，并且尽量缩短加热时间，以减少维生素C在烹饪过程中的流失。","words":[["维生素","wéishēngsù","비타민"],["贾思勰","Jiǎ Sīxié","가사협"],["齐民要术","Qímín Yàoshù","제민요술"],["制曲","zhìqū","누룩을 만들다"],["限流","xiànliú","인원을 통제하다"],["换乘","huànchéng","환승하다"]],"tr":["영양학자들은 잎채소를 조리할 때 먼저 씻고 나중에 썰며, 조리 과정에서 비타민 C가 빠져나가지 않도록 가열 시간을 되도록 줄이라고 권한다.","북위 가사협이 지은 『제민요술』에는 누룩 만들기, 술 빚기, 장 담그기 등 수십 가지 농부산물 가공법이 자세히 실려 있다.","지하철 출근 시간대에는 일부 환승역에서 인원 제한 조치를 해 승객의 안전과 역 안 질서를 지킨다.","운동할 시간이 없다고 늘 불평하는 사람도 사실 하루에 휴대폰을 30분만 덜 보면 운동할 시간을 짜낼 수 있다."],"ow":[[["营养学家","yíngyǎngxuéjiā","영양학자"],["烹饪","pēngrèn","조리하다"],["维生素","wéishēngsù","비타민"],["流失","liúshī","유실되다"]],[["北魏","Běi Wèi","북위"],["贾思勰","Jiǎ Sīxié","가사협"],["齐民要术","Qímín Yàoshù","제민요술"],["制曲","zhìqū","누룩을 만들다"],["农副产品","nóngfù chǎnpǐn","농부산물"]],[["高峰","gāofēng","러시아워"],["换乘站","huànchéngzhàn","환승역"],["限流","xiànliú","인원 제한"],["秩序","zhìxù","질서"]],[["抱怨","bàoyuàn","불평하다"],["刷","shuā","(휴대폰을) 넘겨 보다"],["挤出","jǐchū","짜내다"],["锻炼","duànliàn","단련"]]]},{"o":["这支研究团队把关于野生大豆耐盐碱基因的最新研究成果写成论文，发表了在国际权威期刊上。","我国的筷子文化源远流长，早在商代就已出现了用青铜制成的箸。","冬季气候干燥，人们容易出现口干、皮肤瘙痒等不适，适当食用梨、银耳等食物可以起到滋阴润燥的作用。","有些人习惯在睡前喝一杯酒来帮助入睡，其实酒精虽然能让人较快入睡，却会降低后半夜的睡眠质量。"],"a":0,"type":"개사구 위치","why":"“发表了在……上”은 어순이 틀렸다. “发表在……上” 또는 “在……上发表了”라고 해야 한다.","fix":"这支研究团队把关于野生大豆耐盐碱基因的最新研究成果写成论文，发表在了国际权威期刊上。","words":[["耐盐碱","nàiyánjiǎn","염분·알칼리에 강하다"],["基因","jīyīn","유전자"],["源远流长","yuán yuǎn liú cháng","역사가 유구하다"],["箸","zhù","젓가락(옛말)"],["瘙痒","sàoyǎng","가렵다"],["银耳","yín'ěr","흰목이버섯"],["滋阴润燥","zī yīn rùn zào","음을 보하고 건조함을 적시다"]],"tr":["이 연구팀은 야생 콩의 내염성 유전자에 관한 최신 연구 성과를 논문으로 써서 국제 권위지에 발표했다.","우리나라 젓가락 문화는 역사가 깊어, 일찍이 상나라 때 이미 청동으로 만든 젓가락이 나타났다.","겨울은 날씨가 건조해 입이 마르고 피부가 가려운 등 불편이 생기기 쉬운데, 배나 흰목이버섯 같은 음식을 적당히 먹으면 음을 기르고 건조함을 풀어 준다.","어떤 사람은 잠들기 전 술 한 잔으로 잠을 청하는데, 사실 술은 빨리 잠들게 하지만 새벽녘 수면의 질을 떨어뜨린다."],"ow":[[["野生大豆","yěshēng dàdòu","야생 콩"],["盐碱","yánjiǎn","염분과 알칼리"],["基因","jīyīn","유전자"],["权威","quánwēi","권위"],["期刊","qīkān","학술지"]],[["源远流长","yuán yuǎn liú cháng","역사가 유구하다"],["商代","Shāng dài","상나라"],["青铜","qīngtóng","청동"],["箸","zhù","젓가락"]],[["瘙痒","sàoyǎng","가렵다"],["银耳","yín'ěr","흰목이버섯"],["滋阴润燥","zī yīn rùn zào","음을 보하고 건조함을 적시다"]],[["酒精","jiǔjīng","알코올"],["入睡","rùshuì","잠들다"],["后半夜","hòubànyè","한밤 이후 새벽"]]]},{"o":["调查显示，超过四成的受访大学生表示自己存在不同程度的拖延症，其中以临近考试时最为明显。","宋代的《东京梦华录》记录了北宋都城的饮食风俗，书中提到的各类小吃多达上百种。","祖屋堂屋正中摆放着木头的一张古朴厚重的八仙桌，逢年过节时全家人便围坐在桌旁吃团圆饭。","这片海域由于常年受到寒暖流交汇的影响，饵料丰富，成为了我国著名的渔场之一。"],"a":2,"type":"관형어 순서","why":"수량 “一张”이 관형어 맨 앞에 오고 재료 “木头”는 명사 바로 앞에 와야 한다.","fix":"祖屋堂屋正中摆放着一张古朴厚重的木头八仙桌，逢年过节时全家人便围坐在桌旁吃团圆饭。","words":[["堂屋","tángwū","대청"],["古朴","gǔpǔ","소박하고 예스럽다"],["八仙桌","bāxiānzhuō","팔선탁(네모 식탁)"],["拖延症","tuōyánzhèng","미루는 버릇"],["东京梦华录","Dōngjīng Mènghuá Lù","동경몽화록"],["饵料","ěrliào","먹이"],["渔场","yúchǎng","어장"]],"tr":["조사에 따르면 응답한 대학생의 40퍼센트 이상이 정도의 차이는 있어도 미루는 버릇이 있다고 답했으며, 그중 시험이 다가올 때 가장 두드러졌다.","송나라 『동경몽화록』은 북송 도읍의 음식 풍속을 기록했는데, 책에 나오는 각종 간식은 백 가지가 넘는다.","옛집 대청 한가운데에는 예스럽고 묵직한 나무 팔선상이 놓여 있어, 명절이면 온 식구가 둘러앉아 함께 단란한 식사를 한다.","이 해역은 일 년 내내 한류와 난류가 만나는 영향을 받아 먹이가 풍부해, 우리나라의 이름난 어장이 되었다."],"ow":[[["受访","shòufǎng","인터뷰를 받다"],["拖延症","tuōyánzhèng","미루는 버릇"],["临近","línjìn","임박하다"]],[["东京梦华录","Dōngjīng Mènghuá Lù","동경몽화록"],["北宋","Běi Sòng","북송"],["都城","dūchéng","도읍"],["风俗","fēngsú","풍속"]],[["祖屋","zǔwū","대대로 내려온 집"],["堂屋","tángwū","대청"],["古朴","gǔpǔ","예스럽고 소박하다"],["八仙桌","bāxiānzhuō","팔선상(사각 탁자)"],["团圆饭","tuányuánfàn","가족 모임 식사"]],[["海域","hǎiyù","해역"],["寒暖流","hánnuǎnliú","한류와 난류"],["交汇","jiāohuì","합류하다"],["饵料","ěrliào","먹이"],["渔场","yúchǎng","어장"]]]},{"o":["长期在强光下工作而不佩戴防护眼镜，可能导致视网膜受损，严重时甚至会造成视力永久下降。","“蒸”是一种古老的我国传统烹饪技法，早在新石器时代，先民们就已经开始用陶甗来蒸制食物了。","这所大学的图书馆每到期末考试周便一座难求，许多学生天不亮就到门口排队。","海獭进食时会仰浮在水面上，把石块放在胸前，用来敲开贝类的硬壳。"],"a":1,"type":"관형어 순서","why":"소속을 나타내는 “我国”가 관형어 맨 앞에 와야 한다.","fix":"“蒸”是我国一种古老的传统烹饪技法，早在新石器时代，先民们就已经开始用陶甗来蒸制食物了。","words":[["技法","jìfǎ","기법"],["新石器时代","xīnshíqì shídài","신석기 시대"],["甗","yǎn","언(고대 찜 그릇)"],["视网膜","shìwǎngmó","망막"],["一座难求","yí zuò nán qiú","자리 잡기 어렵다"],["海獭","hǎitǎ","해달"]],"tr":["강한 빛 아래서 보호안경 없이 오래 일하면 망막이 손상될 수 있고, 심하면 시력이 영구히 떨어지기도 한다.","'찜'은 우리나라의 오래된 전통 조리법으로, 일찍이 신석기 시대에 사람들은 이미 질그릇 시루로 음식을 쪄 먹기 시작했다.","이 대학 도서관은 기말시험 기간마다 자리 하나 얻기 어려워, 많은 학생이 날이 밝기도 전에 문 앞에 줄을 선다.","해달은 먹이를 먹을 때 물 위에 드러누워 돌을 가슴에 올려 두고 조개의 단단한 껍데기를 깨는 데 쓴다."],"ow":[[["防护","fánghù","보호"],["视网膜","shìwǎngmó","망막"],["永久","yǒngjiǔ","영구"]],[["烹饪","pēngrèn","조리"],["技法","jìfǎ","기법"],["新石器时代","xīnshíqì shídài","신석기 시대"],["陶甗","táoyǎn","질그릇 시루"]],[["一座难求","yí zuò nán qiú","자리 얻기 어렵다"],["排队","páiduì","줄을 서다"]],[["海獭","hǎitǎ","해달"],["仰浮","yǎngfú","누워서 뜨다"],["贝类","bèilèi","조개류"],["硬壳","yìngké","단단한 껍데기"]]]},{"o":["鲸落是指鲸死亡后沉入海底的过程，一具鲸的遗骸可以供养一个小型生态系统长达数十年。","受全球变暖影响，一些高山植物正被迫向更高海拔的地带迁移，生存空间日益缩小。","他坚持每天清晨在公园里慢跑五公里，十年来风雨无阻，从未间断。","每逢春节，母亲都会拿出那套精美的她外婆的青花瓷餐具，郑重地摆满一桌年夜饭。"],"a":3,"type":"관형어 순서","why":"소유자 “她外婆的”가 “那套精美的”보다 앞에 와야 한다.","fix":"每逢春节，母亲都会拿出她外婆的那套精美的青花瓷餐具，郑重地摆满一桌年夜饭。","words":[["青花瓷","qīnghuācí","청화자기"],["郑重","zhèngzhòng","정중하다"],["年夜饭","niányèfàn","섣달그믐 저녁밥"],["鲸落","jīngluò","고래 낙하"],["遗骸","yíhái","유해"],["风雨无阻","fēng yǔ wú zǔ","비바람에도 거르지 않다"]],"tr":["고래 낙하란 고래가 죽은 뒤 해저로 가라앉는 과정을 말하며, 고래 한 마리의 사체는 작은 생태계를 수십 년 동안 먹여 살릴 수 있다.","지구 온난화의 영향으로 일부 고산 식물은 더 높은 곳으로 밀려 올라가고 있어 살 곳이 갈수록 줄고 있다.","그는 매일 새벽 공원에서 5킬로미터를 달리는데, 10년 동안 비바람에도 거른 적이 없다.","해마다 설이 되면 어머니는 외할머니가 쓰던 그 정교한 청화자기 식기를 꺼내 정성껏 섣달그믐 밥상을 한 상 가득 차린다."],"ow":[[["鲸落","jīngluò","고래 낙하"],["遗骸","yíhái","유해"],["供养","gōngyǎng","부양하다"],["生态系统","shēngtài xìtǒng","생태계"]],[["迁移","qiānyí","옮겨 가다"],["海拔","hǎibá","해발"],["日益","rìyì","날로"],["缩小","suōxiǎo","줄어들다"]],[["慢跑","mànpǎo","조깅"],["风雨无阻","fēng yǔ wú zǔ","비바람에도 거르지 않다"],["间断","jiànduàn","중단하다"]],[["青花瓷","qīnghuācí","청화자기"],["餐具","cānjù","식기"],["郑重","zhèngzhòng","정중하다"],["年夜饭","niányèfàn","섣달그믐 저녁 식사"]]]},{"o":["茶树喜温暖湿润的气候，而我国的云贵高原恰好具备这样的条件，因此被认为是茶树的原产地。","这款智能音箱可以识别多种方言，对于不会使用手机的老年人来说十分友好。","为查明此次集体食物中毒的原因，疾控中心的工作人员迅速对餐厅剩余的饭菜进行了化验和采样，并于当晚公布了初步结果。","大脑在睡眠中并没有停止工作，而是在整理白天接收到的信息，将其中重要的内容转化为长期记忆。"],"a":2,"type":"동사·사건 순서","why":"샘플을 먼저 채취해야 검사할 수 있으므로 “采样和化验” 순서여야 한다.","fix":"为查明此次集体食物中毒的原因，疾控中心的工作人员迅速对餐厅剩余的饭菜进行了采样和化验，并于当晚公布了初步结果。","words":[["疾控中心","jíkòng zhōngxīn","질병통제센터"],["采样","cǎiyàng","샘플을 채취하다"],["化验","huàyàn","화학 검사하다"],["云贵高原","Yún-Guì Gāoyuán","윈구이 고원"],["原产地","yuánchǎndì","원산지"],["方言","fāngyán","방언"]],"tr":["차나무는 따뜻하고 습한 기후를 좋아하는데, 우리나라 윈구이 고원이 마침 이런 조건을 갖추고 있어 차나무의 원산지로 여겨진다.","이 스마트 스피커는 여러 방언을 알아들어 휴대폰을 쓸 줄 모르는 노인들에게 매우 편리하다.","이번 집단 식중독의 원인을 밝히려고 질병통제센터 직원들은 식당에 남은 음식을 재빨리 검사하고 시료를 채취해 그날 밤 1차 결과를 발표했다.","뇌는 잠자는 동안 일을 멈추는 것이 아니라 낮에 받아들인 정보를 정리해 그중 중요한 것을 장기 기억으로 바꾼다."],"ow":[[["云贵高原","Yún-Guì Gāoyuán","윈구이 고원"],["恰好","qiàhǎo","마침"],["具备","jùbèi","갖추다"],["原产地","yuánchǎndì","원산지"]],[["智能音箱","zhìnéng yīnxiāng","스마트 스피커"],["方言","fāngyán","방언"],["友好","yǒuhǎo","친화적이다"]],[["查明","chámíng","밝혀내다"],["食物中毒","shíwù zhòngdú","식중독"],["疾控中心","jíkòng zhōngxīn","질병통제센터"],["化验","huàyàn","화학 검사하다"],["采样","cǎiyàng","시료를 채취하다"]],[["睡眠","shuìmián","수면"],["转化","zhuǎnhuà","바꾸다"],["长期记忆","chángqī jìyì","장기 기억"]]]},{"o":["古人用“春困秋乏夏打盹”来形容季节变化对人体精神状态的影响，这其实与气温和日照时间的变化有关。","社区居委会召开专题会议，认真研究并听取了居民们对小区食堂菜品和价格的意见，决定从下月起进行调整。","这位翻译家用半生心血译完了这部巨著，译文既忠实于原作，又不失汉语的韵味。","沙尘暴虽然会带来严重的空气污染，但它携带的矿物质也为远方的海洋浮游生物提供了养分。"],"a":1,"type":"동사·사건 순서","why":"의견을 먼저 들어야 검토할 수 있으므로 “听取并研究”가 맞다.","fix":"社区居委会召开专题会议，认真听取并研究了居民们对小区食堂菜品和价格的意见，决定从下月起进行调整。","words":[["居委会","jūwěihuì","주민위원회"],["专题","zhuāntí","특정 주제"],["春困秋乏","chūn kùn qiū fá","봄엔 졸리고 가을엔 나른하다"],["打盹","dǎdǔn","졸다"],["韵味","yùnwèi","운치"],["浮游生物","fúyóu shēngwù","플랑크톤"]],"tr":["옛사람들은 '봄엔 나른하고 가을엔 지치고 여름엔 꾸벅 존다'는 말로 계절 변화가 사람의 정신 상태에 주는 영향을 나타냈는데, 이는 사실 기온과 일조 시간의 변화와 관계가 있다.","주민위원회는 특별 회의를 열어 단지 식당의 메뉴와 가격에 대한 주민들의 의견을 진지하게 듣고 검토한 뒤, 다음 달부터 조정하기로 했다.","이 번역가는 반평생의 정성을 들여 이 대작을 다 옮겼는데, 번역문은 원작에 충실하면서도 중국어의 운치를 잃지 않았다.","황사는 심한 대기 오염을 가져오지만, 그것이 실어 나르는 광물질은 먼 바다의 플랑크톤에게 양분을 공급하기도 한다."],"ow":[[["春困秋乏","chūn kùn qiū fá","봄엔 나른, 가을엔 피곤"],["打盹","dǎdǔn","꾸벅 졸다"],["日照","rìzhào","일조"]],[["居委会","jūwěihuì","주민위원회"],["专题","zhuāntí","특정 주제"],["听取","tīngqǔ","청취하다"],["菜品","càipǐn","요리 종류"]],[["翻译家","fānyìjiā","번역가"],["心血","xīnxuè","심혈"],["巨著","jùzhù","대작"],["忠实","zhōngshí","충실하다"],["韵味","yùnwèi","운치"]],[["沙尘暴","shāchénbào","황사, 모래폭풍"],["携带","xiédài","지니다"],["矿物质","kuàngwùzhì","광물질"],["浮游生物","fúyóu shēngwù","플랑크톤"]]]}],[{"o":["不是每一种野生菌都可以食用，有些毒蘑菇的外形与可食用菌极为相似，稍不留神便会误食中毒。","这座城市的老城墙在上世纪被大量拆除，如今残存的几段已被列为重点文物保护单位。","尽管是清淡的白粥还是浓油赤酱的红烧肉，这位老厨师都能做出令人回味无穷的味道。","长期睡眠不足的人，即使白天补觉，也很难完全弥补夜间缺失的深度睡眠。"],"a":2,"type":"짝 오류","why":"“……还是……，都”는 “无论/不管”과 짝을 이룬다. “尽管”은 맞지 않는다.","fix":"无论是清淡的白粥还是浓油赤酱的红烧肉，这位老厨师都能做出令人回味无穷的味道。","words":[["浓油赤酱","nóng yóu chì jiàng","기름지고 간장 색이 진한"],["回味无穷","huí wèi wú qióng","여운이 오래 남다"],["野生菌","yěshēngjūn","야생 버섯"],["稍不留神","shāo bù liú shén","조금만 방심하면"],["残存","cáncún","남아 있다"],["弥补","míbǔ","메우다"]],"tr":["모든 야생 버섯을 먹을 수 있는 것은 아니며, 어떤 독버섯은 생김새가 식용 버섯과 매우 비슷해 조금만 방심해도 잘못 먹고 중독된다.","이 도시의 옛 성벽은 지난 세기에 대부분 헐렸고, 지금 남아 있는 몇 구간은 중점 문화재 보호 단위로 지정되었다.","담백한 흰죽이든 기름지고 간장 맛이 진한 훙사오러우든, 이 노요리사는 두고두고 생각나는 맛을 낸다.","오랫동안 잠이 부족한 사람은 낮에 잠을 보충해도 밤에 놓친 깊은 잠을 완전히 메우기 어렵다."],"ow":[[["野生菌","yěshēngjūn","야생 버섯"],["毒蘑菇","dúmógu","독버섯"],["稍不留神","shāo bù liúshén","조금만 방심하면"],["误食","wùshí","잘못 먹다"]],[["城墙","chéngqiáng","성벽"],["拆除","chāichú","철거하다"],["残存","cáncún","잔존하다"],["文物保护单位","wénwù bǎohù dānwèi","문화재 보호 단위"]],[["浓油赤酱","nóng yóu chì jiàng","기름지고 간장 맛이 진하다"],["红烧肉","hóngshāoròu","훙사오러우(돼지고기 조림)"],["回味无穷","huíwèi wú qióng","여운이 끝없다"]],[["补觉","bǔjiào","잠을 보충하다"],["弥补","míbǔ","메우다"],["缺失","quēshī","결손"]]]},{"o":["与其说这是一本菜谱，不如说它是一部记录了半个世纪城市变迁的民间生活史。","非洲的猴面包树能在雨季将大量水分储存在粗壮的树干中，以度过漫长的旱季。","人们常说“早餐要吃好”，因为经过一夜的消耗，身体急需补充能量来应对上午的工作和学习。","只要严格控制好发酵的温度和时间，自制的酸菜才会口感脆爽、酸味纯正。"],"a":3,"type":"짝 오류","why":"“只要”는 “就”와 짝을 이룬다. “只要……才”는 짝이 틀렸다.","fix":"只要严格控制好发酵的温度和时间，自制的酸菜就会口感脆爽、酸味纯正。","words":[["酸菜","suāncài","절인 배추"],["脆爽","cuìshuǎng","아삭하고 시원하다"],["纯正","chúnzhèng","순수하다"],["菜谱","càipǔ","요리책"],["猴面包树","hóumiànbāoshù","바오밥나무"],["旱季","hànjì","건기"]],"tr":["이것은 요리책이라기보다 반세기 동안의 도시 변화를 기록한 민간 생활사라고 해야 한다.","아프리카의 바오바브나무는 우기에 굵은 줄기에 많은 물을 저장해 긴 건기를 넘긴다.","사람들이 흔히 '아침을 잘 먹어야 한다'고 하는 것은, 밤새 에너지를 쓴 몸이 오전의 일과 공부를 감당하려면 에너지를 시급히 보충해야 하기 때문이다.","발효 온도와 시간만 잘 조절하면 집에서 담근 쏸차이도 아삭하고 신맛이 깔끔해진다."],"ow":[[["与其说","yǔqí shuō","~라기보다"],["菜谱","càipǔ","요리책"],["变迁","biànqiān","변천"]],[["猴面包树","hóumiànbāoshù","바오바브나무"],["雨季","yǔjì","우기"],["粗壮","cūzhuàng","굵고 튼튼하다"],["旱季","hànjì","건기"]],[["消耗","xiāohào","소모"],["急需","jíxū","시급히 필요로 하다"],["补充","bǔchōng","보충하다"]],[["发酵","fājiào","발효"],["酸菜","suāncài","쏸차이(절인 배추)"],["脆爽","cuìshuǎng","아삭하다"],["纯正","chúnzhèng","순수하다"]]]},{"o":["如果不经过反复的晾晒和揉捻，新采摘的茶青才无法形成紧结的外形和饱满的滋味。","不仅年轻人热衷于在社交平台上分享美食，就连不少老年人也学会了拍照打卡。","地球上的潮汐现象主要是由月球的引力引起的，太阳的引力也在其中起到了一定的作用。","这部纪录片之所以能打动人心，在于它没有刻意煽情，而是忠实记录了普通人的日常。"],"a":0,"type":"짝 오류","why":"“如果”는 “就”와 짝을 이룬다. “如果……才”는 짝이 틀렸다.","fix":"如果不经过反复的晾晒和揉捻，新采摘的茶青就无法形成紧结的外形和饱满的滋味。","words":[["晾晒","liàngshài","햇볕에 말리다"],["揉捻","róuniǎn","비비다(차 가공)"],["茶青","cháqīng","생찻잎"],["紧结","jǐnjié","단단히 말리다"],["热衷","rèzhōng","열중하다"],["潮汐","cháoxī","조석"],["煽情","shānqíng","감정을 자극하다"]],"tr":["거듭 볕에 말리고 비비지 않으면, 갓 딴 찻잎은 단단히 말린 모양과 풍부한 맛을 갖출 수 없다.","젊은이들만 SNS에 음식 사진을 즐겨 올리는 것이 아니라, 많은 노인도 사진을 찍어 인증하는 법을 배웠다.","지구의 조석 현상은 주로 달의 인력 때문에 생기며, 태양의 인력도 어느 정도 작용한다.","이 다큐멘터리가 사람들의 마음을 움직인 것은 억지로 감동을 짜내지 않고 보통 사람들의 일상을 충실히 기록했기 때문이다."],"ow":[[["晾晒","liàngshài","볕에 말리다"],["揉捻","róuniǎn","비비다"],["茶青","cháqīng","갓 딴 찻잎"],["紧结","jǐnjié","단단히 말리다"],["饱满","bǎomǎn","풍부하다"]],[["热衷","rèzhōng","열중하다"],["社交平台","shèjiāo píngtái","소셜 미디어"],["打卡","dǎkǎ","인증하다"]],[["潮汐","cháoxī","조석"],["引力","yǐnlì","인력"]],[["纪录片","jìlùpiàn","다큐멘터리"],["刻意","kèyì","일부러"],["煽情","shānqíng","감정을 자극하다"],["忠实","zhōngshí","충실하다"]]]},{"o":["长期使用耳机大音量收听音乐，会对内耳的毛细胞造成不可逆的损伤，进而导致听力下降。","只要掌握了和面、醒面和抻拉的要领，就普通家庭的厨房里也能做出筋道爽滑、不输面馆的手工拉面。","这位老人退休后迷上了园艺，把自家的小阳台打造成了一座四季花开不断的空中花园。","火锅起源于何时，学界至今尚无定论，但重庆、四川一带的麻辣火锅无疑是其中最具代表性的一种。"],"a":1,"type":"관련사 위치","why":"부사인 관련사 “就”는 주어나 장소어 앞이 아니라 동사 바로 앞에 와야 한다.","fix":"只要掌握了和面、醒面和抻拉的要领，在普通家庭的厨房里就能做出筋道爽滑、不输面馆的手工拉面。","words":[["醒面","xǐngmiàn","반죽을 숙성시키다"],["抻拉","chēnlā","잡아 늘이다"],["筋道","jīndao","쫄깃하다"],["毛细胞","máoxìbāo","유모세포"],["不可逆","bùkěnì","되돌릴 수 없다"],["定论","dìnglùn","정론"]],"tr":["이어폰으로 큰 소리의 음악을 오래 들으면 내이의 털세포가 되돌릴 수 없게 손상되어 청력이 떨어진다.","반죽하기, 숙성하기, 늘이기의 요령만 익히면 보통 가정 부엌에서도 쫄깃하고 매끄러워 국숫집 못지않은 수타면을 만들 수 있다.","이 노인은 은퇴 후 원예에 빠져 자기 집 작은 발코니를 사계절 꽃이 끊이지 않는 공중 정원으로 꾸몄다.","훠궈가 언제 생겼는지는 학계에서 아직 정설이 없지만, 충칭과 쓰촨 일대의 마라 훠궈가 그 가운데 가장 대표적인 것임은 틀림없다."],"ow":[[["内耳","nèi'ěr","내이"],["毛细胞","máoxìbāo","털세포"],["不可逆","bùkěnì","되돌릴 수 없다"],["损伤","sǔnshāng","손상"]],[["要领","yàolǐng","요령"],["醒面","xǐngmiàn","반죽을 숙성시키다"],["抻拉","chēnlā","늘이다"],["筋道","jīndao","쫄깃하다"],["拉面","lāmiàn","수타면"]],[["园艺","yuányì","원예"],["阳台","yángtái","발코니"],["打造","dǎzào","만들다"]],[["火锅","huǒguō","훠궈"],["学界","xuéjiè","학계"],["定论","dìnglùn","정설"],["麻辣","málà","얼얼하고 맵다"]]]},{"o":["我国北方民间有“冬至饺子夏至面”的说法，据说冬至吃饺子是为了纪念医圣张仲景。","因为这种野菜只在清明前后的短短十几天里最为鲜嫩，当地人所以都会赶在这段时间上山采摘。","城市夜间过度的人工照明不仅干扰了萤火虫等昆虫的繁殖，也影响了居民的睡眠。","一款新药从实验室研发到最终上市，往往需要经过十年以上的时间和数十亿元的投入。"],"a":1,"type":"관련사 위치","why":"접속사 “所以”는 뒤 절의 주어 “当地人” 앞에 와야 한다.","fix":"因为这种野菜只在清明前后的短短十几天里最为鲜嫩，所以当地人都会赶在这段时间上山采摘。","words":[["野菜","yěcài","산나물"],["鲜嫩","xiānnèn","신선하고 연하다"],["冬至","Dōngzhì","동지"],["医圣","yīshèng","의성"],["萤火虫","yínghuǒchóng","반딧불이"],["研发","yánfā","연구 개발하다"]],"tr":["우리나라 북방 민간에는 '동지엔 만두, 하지엔 국수'라는 말이 있는데, 동지에 만두를 먹는 것은 의성 장중경을 기리기 위해서라고 한다.","이 산나물은 청명 앞뒤 열흘 남짓한 짧은 기간에만 가장 연하기 때문에, 그곳 사람들은 모두 이때를 맞춰 산에 올라 캔다.","도시의 밤 과잉 인공조명은 반딧불이 같은 곤충의 번식을 방해할 뿐 아니라 주민들의 수면에도 영향을 준다.","신약 하나가 실험실 연구개발에서 출시까지 가려면 흔히 10년 넘는 시간과 수십억 위안의 투자가 필요하다."],"ow":[[["冬至","dōngzhì","동지"],["夏至","xiàzhì","하지"],["医圣","yīshèng","의성"],["张仲景","Zhāng Zhòngjǐng","장중경"]],[["野菜","yěcài","산나물"],["清明","qīngmíng","청명"],["鲜嫩","xiānnèn","연하다"],["采摘","cǎizhāi","따다"]],[["照明","zhàomíng","조명"],["干扰","gānrǎo","방해하다"],["萤火虫","yínghuǒchóng","반딧불이"],["繁殖","fánzhí","번식"]],[["研发","yánfā","연구개발"],["上市","shàngshì","출시하다"],["投入","tóurù","투입"]]]},{"o":["腌制食品虽然风味独特，但其中含有的亚硝酸盐若长期过量摄入，会对健康产生危害。","这位作家晚年隐居山中，每日读书、种菜、写作，过着近乎与世隔绝的生活。","在近海网箱中养殖的大黄鱼，由于活动空间有限，肉质往往不如野生大黄鱼那样紧实鲜美。","这种菌菇富含蛋白质和多种氨基酸，营养价值很高，却深受素食者的青睐。"],"a":3,"type":"논리 관계(역접 오용)","why":"영양가가 높아서 채식주의자에게 인기가 있는 것이므로 역접 “却”가 아니라 “因此”를 써야 한다.","fix":"这种菌菇富含蛋白质和多种氨基酸，营养价值很高，因此深受素食者的青睐。","words":[["菌菇","jūngū","버섯"],["氨基酸","ānjīsuān","아미노산"],["青睐","qīnglài","호감, 인기"],["亚硝酸盐","yàxiāosuānyán","아질산염"],["隐居","yǐnjū","은거하다"],["与世隔绝","yǔ shì gé jué","세상과 단절되다"],["网箱","wǎngxiāng","가두리(그물 양식장)"],["紧实","jǐnshí","탄탄하다"]],"tr":["절임 식품은 맛이 독특하지만, 그 속의 아질산염을 오래 지나치게 섭취하면 건강에 해롭다.","이 작가는 말년에 산에 은거해 날마다 책 읽고 채소 기르고 글 쓰며 세상과 거의 단절된 삶을 살았다.","연안 가두리에서 기르는 참조기는 움직일 공간이 좁아 살이 대개 자연산만큼 단단하고 맛있지 않다.","이 버섯은 단백질과 여러 아미노산이 풍부해 영양가가 높아 채식주의자들에게 사랑받는다."],"ow":[[["腌制","yānzhì","절이다"],["亚硝酸盐","yàxiāosuānyán","아질산염"],["摄入","shèrù","섭취"]],[["晚年","wǎnnián","말년"],["隐居","yǐnjū","은거하다"],["与世隔绝","yǔ shì gé jué","세상과 단절되다"]],[["网箱","wǎngxiāng","가두리"],["养殖","yǎngzhí","양식하다"],["大黄鱼","dàhuángyú","참조기"],["紧实","jǐnshí","단단하다"]],[["菌菇","jūngū","버섯"],["蛋白质","dànbáizhì","단백질"],["氨基酸","ānjīsuān","아미노산"],["素食者","sùshízhě","채식주의자"],["青睐","qīnglài","호감"]]]},{"o":["人在饥饿时注意力往往难以集中，这是因为大脑所需的葡萄糖供应暂时不足。","这项技术能把海水中的盐分去除，使其变为可供饮用的淡水，为缺水的海岛居民带来了福音。","这种用糯米和芝麻做成的点心在当地极受欢迎，不仅是全国各地的游客，甚至本地人也常常专程赶来购买。","冰岛虽然地处北极圈附近，但由于地热资源丰富，许多家庭全年都能用上廉价的地热热水。"],"a":2,"type":"논리 관계(점층 오용)","why":"점층은 약한 것에서 강한 것으로 가야 한다. 현지인보다 전국에서 찾아오는 관광객이 더 놀라운 일인데 “甚至” 뒤에 현지인을 두어 순서가 거꾸로다.","fix":"这种用糯米和芝麻做成的点心在当地极受欢迎，不仅本地人爱吃，甚至全国各地的游客也常常专程赶来购买。","words":[["芝麻","zhīma","참깨"],["专程","zhuānchéng","일부러 찾아가다"],["葡萄糖","pútáotáng","포도당"],["福音","fúyīn","기쁜 소식"],["地热","dìrè","지열"],["廉价","liánjià","값싸다"]],"tr":["사람은 배가 고프면 집중하기 어려운데, 이는 뇌에 필요한 포도당 공급이 잠시 모자라기 때문이다.","이 기술은 바닷물의 염분을 없애 마실 수 있는 담수로 바꿔, 물이 부족한 섬 주민들에게 기쁜 소식이 되었다.","찹쌀과 참깨로 만든 이 과자는 그 지역에서 인기가 매우 높아, 그곳 사람들은 물론 전국 각지의 관광객까지 일부러 사러 온다.","아이슬란드는 북극권 가까이에 있지만 지열 자원이 풍부해 많은 가정이 일 년 내내 값싼 지열 온수를 쓴다."],"ow":[[["葡萄糖","pútáotáng","포도당"],["供应","gōngyìng","공급"]],[["盐分","yánfèn","염분"],["淡水","dànshuǐ","담수"],["福音","fúyīn","기쁜 소식"]],[["糯米","nuòmǐ","찹쌀"],["芝麻","zhīma","참깨"],["点心","diǎnxin","과자, 간식"],["专程","zhuānchéng","일부러"]],[["冰岛","Bīngdǎo","아이슬란드"],["北极圈","běijíquān","북극권"],["地热","dìrè","지열"],["廉价","liánjià","값싸다"]]]},{"o":["汤圆是元宵节必不可少的应节食品，可是它圆圆的外形寓意着阖家团圆、和和美美。","长时间待在空调房里，室内外温差过大，人体的体温调节功能容易失调，从而引发所谓的“空调病”。","这座城市通过建设“海绵城市”，让雨水能够被自然地吸收、渗透和净化，有效缓解了内涝问题。","古希腊哲学家苏格拉底一生述而不作，他的思想主要是通过学生柏拉图的著作才得以流传下来。"],"a":0,"type":"논리 관계(역접 오용)","why":"앞뒤 내용이 반대되지 않는데 역접 “可是”를 썼다. “而且”를 쓰거나 빼야 한다.","fix":"汤圆是元宵节必不可少的应节食品，而且它圆圆的外形寓意着阖家团圆、和和美美。","words":[["汤圆","tāngyuán","탕위안(찹쌀 경단)"],["应节","yìngjié","명절에 맞추다"],["阖家团圆","hé jiā tuán yuán","온 가족이 모이다"],["失调","shītiáo","균형이 깨지다"],["内涝","nèilào","도시 침수"],["述而不作","shù ér bú zuò","전하기만 하고 짓지 않다"]],"tr":["탕위안은 정월 대보름에 빠질 수 없는 절기 음식인데, 그 둥근 모양은 온 가족이 모여 화목함을 뜻한다.","에어컨 켠 방에 오래 있으면 실내외 온도 차가 너무 커서 체온 조절 기능이 흐트러지기 쉬워, 이른바 '냉방병'이 생긴다.","이 도시는 '스펀지 도시'를 만들어 빗물이 자연스럽게 흡수·침투·정화되게 해 침수 문제를 효과적으로 줄였다.","고대 그리스 철학자 소크라테스는 평생 말로만 전하고 글을 쓰지 않았으며, 그의 사상은 주로 제자 플라톤의 저작을 통해 전해졌다."],"ow":[[["汤圆","tāngyuán","탕위안(찹쌀 경단)"],["元宵节","Yuánxiāo jié","정월 대보름"],["寓意","yùyì","담긴 뜻"],["阖家团圆","hé jiā tuányuán","온 가족이 모이다"]],[["调节","tiáojié","조절"],["失调","shītiáo","균형을 잃다"],["空调病","kōngtiáobìng","냉방병"]],[["海绵城市","hǎimián chéngshì","스펀지 도시"],["渗透","shèntòu","스며들다"],["净化","jìnghuà","정화"],["内涝","nèilào","도시 침수"]],[["苏格拉底","Sūgélādǐ","소크라테스"],["述而不作","shù ér bú zuò","전하되 짓지 않다"],["柏拉图","Bólātú","플라톤"],["著作","zhùzuò","저작"]]]},{"o":["茶多酚是茶叶中的主要功能成分，具有抗氧化的作用，但空腹大量饮用浓茶反而可能刺激胃肠。","这位老人每天骑着三轮车穿街走巷，把新鲜的豆腐送到附近几个小区的居民家门口。","人们发现，在城市中种植行道树不仅能遮阴降温，还能在一定程度上吸附空气中的颗粒物。","近年来，营养学界关于“少食多餐”是否真正有益于控制血糖展开了广泛而深入的讨论。"],"a":3,"type":"개사 오용","why":"“关于”로 된 구는 주어 뒤 부사어 자리에 올 수 없다. 주어 뒤에서는 대상을 나타내는 “对”를 써야 한다.","fix":"近年来，营养学界对“少食多餐”是否真正有益于控制血糖展开了广泛而深入的讨论。","words":[["少食多餐","shǎo shí duō cān","적게 자주 먹다"],["血糖","xuètáng","혈당"],["茶多酚","cháduōfēn","차 폴리페놀"],["抗氧化","kàngyǎnghuà","항산화"],["穿街走巷","chuān jiē zǒu xiàng","골목골목 누비다"],["颗粒物","kēlìwù","미세먼지"]],"tr":["차 폴리페놀은 찻잎의 주요 기능 성분으로 항산화 작용이 있지만, 빈속에 진한 차를 많이 마시면 오히려 위장을 자극할 수 있다.","이 노인은 매일 삼륜차를 타고 골목골목을 다니며 갓 만든 두부를 근처 몇 단지 주민의 집 앞까지 배달한다.","도시에 가로수를 심으면 그늘을 만들어 온도를 낮출 뿐 아니라 공기 중 미세먼지를 어느 정도 흡착한다는 것이 밝혀졌다.","최근 영양학계는 '조금씩 자주 먹기'가 정말 혈당 관리에 도움이 되는지를 두고 폭넓고 깊이 있는 토론을 벌였다."],"ow":[[["茶多酚","cháduōfēn","차 폴리페놀"],["抗氧化","kàngyǎnghuà","항산화"],["空腹","kōngfù","빈속"],["刺激","cìjī","자극하다"]],[["三轮车","sānlúnchē","삼륜차"],["穿街走巷","chuān jiē zǒu xiàng","골목을 누비다"],["豆腐","dòufu","두부"]],[["行道树","xíngdàoshù","가로수"],["遮阴","zhēyīn","그늘을 지우다"],["吸附","xīfù","흡착하다"],["颗粒物","kēlìwù","미세먼지"]],[["营养学界","yíngyǎng xuéjiè","영양학계"],["少食多餐","shǎo shí duō cān","조금씩 자주 먹다"],["血糖","xuètáng","혈당"]]]},{"o":["蘑菇既不是植物也不是动物，而是属于真菌界，它们通过释放孢子来繁衍后代。","在许多旅居海外多年的华人来说，一碗热腾腾的家乡面条往往是最能慰藉乡愁的食物。","该地区正在推广稻田养鱼的生态种养模式，既提高了土地利用率，又减少了化肥和农药的使用。","这首曲子的旋律简单质朴，却饱含着作曲家对故乡山水的深情眷恋。"],"a":1,"type":"개사 오용·섞임","why":"“对……来说”와 “在……看来”가 섞여 “在……来说”가 되었다.","fix":"对许多旅居海外多年的华人来说，一碗热腾腾的家乡面条往往是最能慰藉乡愁的食物。","words":[["旅居","lǚjū","타지에 머물다"],["慰藉","wèijiè","위로하다"],["乡愁","xiāngchóu","향수"],["真菌","zhēnjūn","진균"],["孢子","bāozǐ","포자"],["眷恋","juànliàn","그리워하다"]],"tr":["버섯은 식물도 동물도 아닌 균계에 속하며, 포자를 퍼뜨려 번식한다.","해외에서 오래 산 많은 화교에게는 따끈한 고향 국수 한 그릇이 향수를 가장 잘 달래 주는 음식이다.","이 지역은 논에서 물고기를 함께 기르는 생태 농법을 보급하고 있어, 토지 이용률을 높이는 동시에 화학비료와 농약 사용을 줄였다.","이 곡은 선율이 단순하고 소박하지만, 고향 산천을 향한 작곡가의 깊은 그리움이 가득 담겨 있다."],"ow":[[["蘑菇","mógu","버섯"],["真菌","zhēnjūn","진균"],["孢子","bāozǐ","포자"],["繁衍","fányǎn","번식하다"]],[["旅居","lǚjū","타향에 머물다"],["热腾腾","rètēngtēng","따끈따끈하다"],["慰藉","wèijiè","위로하다"],["乡愁","xiāngchóu","향수"]],[["稻田养鱼","dàotián yǎng yú","논 양어"],["种养","zhòngyǎng","재배와 사육"],["化肥","huàféi","화학비료"],["农药","nóngyào","농약"]],[["旋律","xuánlǜ","선율"],["质朴","zhìpǔ","소박하다"],["饱含","bǎohán","가득 담다"],["眷恋","juànliàn","그리워하다"]]]}],[{"o":["中医提醒，服用含有人参的补益类汤药期间，切忌不要同时食用萝卜，以免削弱药效。","这家老酱菜坊能经营三百多年而不衰，靠的正是对选料和工艺毫不妥协的坚持。","由于潮汐摩擦的作用，地球的自转正在极其缓慢地减速，这意味着在遥远的未来，一天的长度会略微变长。","没有一位参赛的厨师不为这次比赛精心准备，每一道作品都凝聚着他们多年的经验与心血。"],"a":0,"type":"이중 부정","why":"“切忌”가 이미 ‘절대 하지 말라’는 뜻이라 “不要”를 더하면 ‘먹으라’는 반대 뜻이 된다.","fix":"中医提醒，服用含有人参的补益类汤药期间，切忌同时食用萝卜，以免削弱药效。","words":[["补益","bǔyì","보양하다"],["汤药","tāngyào","탕약"],["切忌","qièjì","절대 삼가다"],["妥协","tuǒxié","타협하다"],["自转","zìzhuàn","자전"],["凝聚","níngjù","응집되다"]],"tr":["한의사들은 인삼이 든 보약을 먹는 동안 약효가 떨어지지 않도록 무를 함께 먹지 말라고 당부한다.","이 오래된 장아찌 공방이 300년 넘게 쇠하지 않고 영업할 수 있었던 것은 재료 선택과 공법에서 조금도 타협하지 않는 고집 덕분이다.","조석 마찰 때문에 지구의 자전은 아주 천천히 느려지고 있으며, 이는 먼 미래에 하루의 길이가 조금 길어진다는 뜻이다.","대회에 참가한 요리사 가운데 이번 대회를 정성껏 준비하지 않은 사람은 하나도 없으며, 작품마다 그들의 오랜 경험과 심혈이 담겨 있다."],"ow":[[["人参","rénshēn","인삼"],["补益","bǔyì","보하다"],["汤药","tāngyào","탕약"],["切忌","qièjì","절대 피하다"],["萝卜","luóbo","무"]],[["酱菜","jiàngcài","장아찌"],["选料","xuǎnliào","재료를 고르다"],["妥协","tuǒxié","타협하다"]],[["潮汐","cháoxī","조석"],["摩擦","mócā","마찰"],["自转","zìzhuàn","자전"],["减速","jiǎnsù","감속"]],[["凝聚","níngjù","응집하다"],["心血","xīnxuè","심혈"]]]},{"o":["未必所有的“网红”餐厅都名副其实，盲目跟风排队往往只会让人失望而归。","人在深度睡眠时，脑脊液会更活跃地清除大脑中积累的代谢废物，这或许是睡眠能让人恢复精力的原因之一。","为了杜绝过期食材不再被端上餐桌，这家餐厅建立了严格的进货登记和每日盘点制度。","这座海岛上的居民世代以捕鱼为生，至今仍保留着出海前祭拜海神的古老习俗。"],"a":2,"type":"이중 부정","why":"“杜绝”(뿌리 뽑다)에 “不再”를 더해 부정이 겹쳐, ‘상한 재료가 다시 오르게 하려고’라는 반대 뜻이 된다.","fix":"为了杜绝过期食材被端上餐桌，这家餐厅建立了严格的进货登记和每日盘点制度。","words":[["杜绝","dùjué","근절하다"],["盘点","pándiǎn","재고를 조사하다"],["网红","wǎnghóng","인터넷 스타"],["名副其实","míng fù qí shí","명실상부하다"],["跟风","gēnfēng","유행을 좇다"],["脑脊液","nǎojǐyè","뇌척수액"],["祭拜","jìbài","제사 지내다"]],"tr":["모든 '왕훙' 맛집이 이름값을 하는 것은 아니어서, 무턱대고 유행 따라 줄을 서면 실망하고 돌아오기 일쑤다.","깊은 잠을 잘 때 뇌척수액이 뇌에 쌓인 대사 노폐물을 더 활발하게 씻어 내는데, 이것이 잠이 기운을 되찾게 하는 까닭 가운데 하나일 것이다.","유통기한이 지난 식재료가 식탁에 오르는 일을 막으려고 이 식당은 엄격한 입고 등록과 매일 재고 점검 제도를 만들었다.","이 섬 주민들은 대대로 고기잡이로 살아왔으며, 지금도 바다에 나가기 전 해신에게 제사 지내는 오랜 풍습을 지키고 있다."],"ow":[[["未必","wèibì","반드시 ~은 아니다"],["网红","wǎnghóng","인터넷 인기"],["名副其实","míng fù qí shí","이름과 실제가 맞다"],["跟风","gēnfēng","유행을 따르다"]],[["脑脊液","nǎojǐyè","뇌척수액"],["代谢","dàixiè","대사"],["废物","fèiwù","노폐물"]],[["杜绝","dùjué","근절하다"],["过期","guòqī","기한이 지나다"],["食材","shícái","식재료"],["盘点","pándiǎn","재고 조사"]],[["世代","shìdài","대대로"],["捕鱼","bǔyú","고기를 잡다"],["祭拜","jìbài","제사 지내다"],["海神","hǎishén","해신"],["习俗","xísú","풍습"]]]},{"o":["我们不能不承认，快节奏的生活方式正在悄然改变着人们一日三餐的饮食结构。","根据新出台的规定，校园周边两百米范围内禁止商家不得销售高糖饮料和辣条等零食。","这套丛书以图文结合的方式，向孩子们介绍了二十多种常见中草药的形态、功效和采收季节。","高温天气下，人体通过大量出汗来散热，因此需要及时补充水分和电解质，以防中暑。"],"a":1,"type":"이중 부정","why":"“禁止”와 “不得”가 겹쳐 부정이 두 번이 되어 ‘팔아야 한다’는 반대 뜻이 된다.","fix":"根据新出台的规定，校园周边两百米范围内禁止商家销售高糖饮料和辣条等零食。","words":[["出台","chūtái","(정책이) 나오다"],["辣条","làtiáo","매운 간식"],["悄然","qiǎorán","조용히"],["丛书","cóngshū","총서"],["中草药","zhōngcǎoyào","중국 약초"],["电解质","diànjiězhì","전해질"],["中暑","zhòngshǔ","더위를 먹다"]],"tr":["빠른 생활 방식이 사람들의 하루 세 끼 식사 구성을 조용히 바꾸고 있다는 것을 우리는 인정하지 않을 수 없다.","새로 나온 규정에 따르면 학교 주변 200미터 안에서는 상인이 고당 음료와 매운 과자 같은 간식을 팔 수 없다.","이 총서는 그림과 글을 곁들여 아이들에게 흔한 한약재 스무여 가지의 생김새, 효능, 채취 시기를 소개했다.","더운 날씨에 몸은 땀을 많이 흘려 열을 식히므로, 더위 먹지 않도록 물과 전해질을 제때 보충해야 한다."],"ow":[[["不能不","bù néng bù","~하지 않을 수 없다"],["悄然","qiǎorán","조용히"],["饮食结构","yǐnshí jiégòu","식사 구성"]],[["出台","chūtái","공포되다"],["禁止","jìnzhǐ","금지하다"],["辣条","làtiáo","라탸오(매운 간식)"],["零食","língshí","간식"]],[["丛书","cóngshū","총서"],["中草药","zhōngcǎoyào","한약재"],["功效","gōngxiào","효능"],["采收","cǎishōu","채취하다"]],[["散热","sànrè","열을 발산하다"],["电解质","diànjiězhì","전해질"],["中暑","zhòngshǔ","더위를 먹다"]]]},{"o":["据统计，今年该市的人均图书阅读量比去年增长了百分之十五，其中电子书所占的比例首次超过纸质书。","唐代诗人卢仝的《七碗茶歌》把饮茶带来的身心愉悦描写得淋漓尽致，被后世茶人反复吟诵。","这座城市的人口在过去二十年里翻了一番，住房和交通的压力随之倍增。","采用真空低温油炸工艺后，这款薯片的含油量比传统工艺降低了两倍，口感却依然酥脆。"],"a":3,"type":"배수 감소","why":"줄어드는 것은 “倍”로 나타낼 수 없다. “降低了三分之二”처럼 분수로 써야 한다.","fix":"采用真空低温油炸工艺后，这款薯片的含油量比传统工艺降低了三分之二，口感却依然酥脆。","words":[["真空","zhēnkōng","진공"],["酥脆","sūcuì","바삭하다"],["卢仝","Lú Tóng","노동(당대 시인)"],["淋漓尽致","lín lí jìn zhì","남김없이 생생하다"],["吟诵","yínsòng","읊다"],["翻一番","fānyìfān","두 배가 되다"]],"tr":["통계에 따르면 올해 이 도시의 1인당 독서량은 작년보다 15퍼센트 늘었고, 그중 전자책 비중이 처음으로 종이책을 넘어섰다.","당나라 시인 노동의 「칠완다가」는 차를 마실 때 느끼는 몸과 마음의 즐거움을 남김없이 그려 내, 후대 다인들이 거듭 읊었다.","이 도시의 인구는 지난 20년 동안 두 배로 늘었고, 주거와 교통의 압박도 그에 따라 배로 커졌다.","진공 저온 튀김 공법을 쓴 뒤로 이 감자칩의 기름 함량은 전통 공법보다 크게 줄었지만 식감은 여전히 바삭하다."],"ow":[[["人均","rénjūn","1인당"],["阅读量","yuèdúliàng","독서량"],["比例","bǐlì","비율"]],[["卢仝","Lú Tóng","노동"],["七碗茶歌","Qī Wǎn Chá Gē","칠완다가"],["淋漓尽致","lín lí jìn zhì","남김없이 생생하다"],["吟诵","yínsòng","읊다"]],[["翻了一番","fān le yì fān","두 배가 되다"],["倍增","bèizēng","배로 늘다"]],[["真空","zhēnkōng","진공"],["油炸","yóuzhá","기름에 튀기다"],["薯片","shǔpiàn","감자칩"],["酥脆","sūcuì","바삭하다"]]]},{"o":["四川的“盖碗茶”由茶碗、茶盖和茶船组成，茶客饮茶时用茶盖轻轻拨动浮叶，别有一番情趣。","猫一天中有超过一半的时间在睡觉，但其中大部分属于浅睡眠，稍有动静便会立刻醒来。","该研究共招募了一千二百名志愿者，其中男性和女性各占一半。","引进自动化流水线以后，这家速冻水饺工厂每批产品的生产周期比原来缩短了一倍，产能大幅提升。"],"a":3,"type":"배수 감소","why":"줄어드는 것은 “倍”로 나타낼 수 없다. “缩短了一半”라고 해야 한다.","fix":"引进自动化流水线以后，这家速冻水饺工厂每批产品的生产周期比原来缩短了一半，产能大幅提升。","words":[["流水线","liúshuǐxiàn","생산 라인"],["速冻","sùdòng","급속 냉동"],["产能","chǎnnéng","생산 능력"],["盖碗茶","gàiwǎnchá","뚜껑 찻잔 차"],["拨动","bōdòng","젓다"],["情趣","qíngqù","정취"],["招募","zhāomù","모집하다"]],"tr":["쓰촨의 '덮개 찻잔 차'는 찻잔, 뚜껑, 받침으로 이루어지며, 차를 마시는 사람이 뚜껑으로 떠 있는 찻잎을 살살 밀어내는 모습이 남다른 정취를 준다.","고양이는 하루의 절반 넘게 잠을 자지만 대부분 얕은 잠이어서 조금만 기척이 있어도 곧바로 깬다.","이 연구에는 지원자 1,200명이 모집되었는데, 남녀가 절반씩이었다.","자동화 생산 라인을 들인 뒤 이 냉동 만두 공장은 한 회분 제품의 생산 주기가 크게 줄어 생산 능력이 대폭 올라갔다."],"ow":[[["盖碗茶","gàiwǎnchá","덮개 찻잔 차"],["茶船","cháchuán","찻잔 받침"],["拨动","bōdòng","밀어 젓다"],["别有一番情趣","bié yǒu yì fān qíngqù","남다른 정취가 있다"]],[["浅睡眠","qiǎn shuìmián","얕은 잠"],["动静","dòngjing","기척"]],[["招募","zhāomù","모집하다"],["志愿者","zhìyuànzhě","지원자"]],[["自动化","zìdònghuà","자동화"],["流水线","liúshuǐxiàn","생산 라인"],["速冻","sùdòng","급속 냉동"],["产能","chǎnnéng","생산 능력"]]]},{"o":["我国的酱油按照酿造工艺的不同，大致可分为高盐稀态和低盐固态两大类。","这次中医药博览会上展出了人参、当归、黄芪、灵芝和名贵中药材等三百多个品种，吸引了大批海内外采购商。","这家医院的营养科会根据患者的病情和体质，制定个性化的饮食方案。","这片古老的森林中栖息着黑熊、金丝猴、红腹锦鸡等多种珍稀野生动物。"],"a":1,"type":"범위·분류 오류","why":"“人参、当归、黄芪、灵芝”는 모두 “中药材”에 속하는데 같은 층위로 나란히 놓았다.","fix":"这次中医药博览会上展出了人参、当归、黄芪、灵芝等三百多个品种的名贵中药材，吸引了大批海内外采购商。","words":[["当归","dāngguī","당귀"],["黄芪","huángqí","황기"],["灵芝","língzhī","영지버섯"],["采购商","cǎigòushāng","바이어"],["稀态","xītài","묽은 상태"],["金丝猴","jīnsīhóu","황금들창코원숭이"],["栖息","qīxī","서식하다"]],"tr":["우리나라 간장은 양조 공법에 따라 대체로 고염 액상과 저염 고상 두 종류로 나뉜다.","이번 중의약 박람회에는 인삼, 당귀, 황기, 영지와 귀한 약재 등 300여 품목이 전시되어 국내외 구매상이 대거 몰렸다.","이 병원 영양과는 환자의 병세와 체질에 따라 개인 맞춤 식단을 짠다.","이 오래된 숲에는 반달가슴곰, 금빛원숭이, 금계 등 여러 희귀 야생동물이 산다."],"ow":[[["酱油","jiàngyóu","간장"],["酿造","niàngzào","양조"],["稀态","xītài","액체 상태"],["固态","gùtài","고체 상태"]],[["博览会","bólǎnhuì","박람회"],["当归","dāngguī","당귀"],["黄芪","huángqí","황기"],["灵芝","língzhī","영지"],["采购商","cǎigòushāng","구매상"]],[["营养科","yíngyǎngkē","영양과"],["体质","tǐzhì","체질"],["个性化","gèxìnghuà","개인 맞춤"]],[["栖息","qīxī","서식하다"],["黑熊","hēixióng","반달가슴곰"],["金丝猴","jīnsīhóu","금빛원숭이"],["红腹锦鸡","hóngfù jǐnjī","금계"]]]},{"o":["这本食谱收录了粤菜、川菜、鲁菜、淮扬菜和中国菜等各大菜系的上百道经典菜肴，并配有详细的步骤图。","人体所需的微量元素虽然含量极少，但一旦缺乏，就可能引起贫血、免疫力下降等多种问题。","这部电影改编自同名畅销小说，导演在保留原著精神的同时，对部分情节作了大胆的删改。","这座城市自有气象观测记录以来的最高气温，出现在半个多世纪前的一个夏天。"],"a":0,"type":"범위·분류 오류","why":"“粤菜·川菜·鲁菜·淮扬菜”는 모두 “中国菜”에 속하는데 같은 층위로 나란히 놓았다.","fix":"这本食谱收录了粤菜、川菜、鲁菜、淮扬菜等中国各大菜系的上百道经典菜肴，并配有详细的步骤图。","words":[["菜系","càixì","요리 계통"],["淮扬菜","Huáiyángcài","화이양 요리"],["微量元素","wēiliàng yuánsù","미량 원소"],["贫血","pínxuè","빈혈"],["改编","gǎibiān","각색하다"],["删改","shāngǎi","삭제·수정하다"]],"tr":["이 요리책은 광둥·쓰촨·산둥·화이양 요리와 중국 요리 등 주요 요리 계통의 대표 요리 백여 가지를 싣고 자세한 단계별 사진도 곁들였다.","사람에게 필요한 미량 원소는 양이 아주 적지만, 모자라면 빈혈이나 면역력 저하 같은 여러 문제가 생길 수 있다.","이 영화는 같은 이름의 베스트셀러 소설을 각색했는데, 감독은 원작의 정신을 살리면서 일부 줄거리를 과감하게 고치고 덜어 냈다.","이 도시에서 기상 관측 기록이 시작된 이래 가장 높은 기온은 반세기 넘게 전의 어느 여름에 나왔다."],"ow":[[["食谱","shípǔ","요리책"],["粤菜","yuècài","광둥 요리"],["鲁菜","lǔcài","산둥 요리"],["淮扬菜","huáiyángcài","화이양 요리"],["菜系","càixì","요리 계통"],["菜肴","càiyáo","요리"]],[["微量元素","wēiliàng yuánsù","미량 원소"],["贫血","pínxuè","빈혈"],["免疫力","miǎnyìlì","면역력"]],[["改编","gǎibiān","각색하다"],["畅销","chàngxiāo","잘 팔리다"],["原著","yuánzhù","원작"],["删改","shāngǎi","고치고 삭제하다"]],[["气象","qìxiàng","기상"],["观测","guāncè","관측"]]]},{"o":["患有慢性胃炎的人应少吃辛辣、生冷和过于油腻的食物，平时要注意饮食规律、细嚼慢咽。","海拔越高，空气中的含氧量越低，因此在高原地区进行剧烈运动更容易感到疲劳。","这家老店的招牌菜是一道秘制酱鸭，从腌制到风干，前后大约需要整整十五天。","在已知的八千多种两栖动物中，蛙类约占百分之八十八。"],"a":2,"type":"자기모순","why":"“大约”(어림)와 “整整”(꼭 그만큼)이 함께 쓰여 앞뒤가 모순된다.","fix":"这家老店的招牌菜是一道秘制酱鸭，从腌制到风干，前后大约需要十五天。","words":[["招牌菜","zhāopáicài","대표 메뉴"],["秘制","mìzhì","비법으로 만든"],["酱鸭","jiàngyā","간장 오리"],["风干","fēnggān","바람에 말리다"],["胃炎","wèiyán","위염"],["细嚼慢咽","xì jiáo màn yàn","꼭꼭 씹어 천천히 삼키다"],["两栖动物","liǎngqī dòngwù","양서류"]],"tr":["만성 위염이 있는 사람은 맵고 차고 너무 기름진 음식을 적게 먹고, 평소 규칙적으로 먹으며 꼭꼭 씹어 천천히 삼켜야 한다.","해발이 높을수록 공기 중 산소 함량이 낮아, 고원에서 격렬한 운동을 하면 더 쉽게 지친다.","이 오래된 가게의 대표 요리는 비법 간장 오리인데, 절이기부터 바람에 말리기까지 꼬박 보름쯤 걸린다.","알려진 8천여 종의 양서류 가운데 개구리류가 약 88퍼센트를 차지한다."],"ow":[[["慢性胃炎","mànxìng wèiyán","만성 위염"],["辛辣","xīnlà","맵다"],["油腻","yóunì","기름지다"],["细嚼慢咽","xì jiáo màn yàn","꼭꼭 씹어 천천히 삼키다"]],[["海拔","hǎibá","해발"],["含氧量","hányǎngliàng","산소 함량"],["剧烈","jùliè","격렬하다"]],[["招牌菜","zhāopáicài","대표 요리"],["秘制","mìzhì","비법으로 만든"],["酱鸭","jiàngyā","간장 오리"],["风干","fēnggān","바람에 말리다"]],[["两栖动物","liǎngqī dòngwù","양서류"],["蛙类","wālèi","개구리류"]]]},{"o":["这道家常小炒做法十分简单，除主料外只需要用到四种调料，即盐、生抽、白糖、香醋和少许胡椒粉。","日本的和食文化重视食材的季节性，讲究在不同的时令品尝当季最新鲜的味道。","如果长期处于焦虑状态，人体会持续分泌压力激素，进而影响消化和免疫功能。","这座古城的街巷布局至今仍保持着唐代的棋盘式格局，被视为研究古代城市规划的活标本。"],"a":0,"type":"자기모순(숫자)","why":"“四种调料”라고 해 놓고 뒤에 다섯 가지를 늘어놓아 숫자가 맞지 않는다.","fix":"这道家常小炒做法十分简单，除主料外只需要用到五种调料，即盐、生抽、白糖、香醋和少许胡椒粉。","words":[["小炒","xiǎochǎo","볶음 요리"],["生抽","shēngchōu","연한 간장"],["胡椒粉","hújiāofěn","후춧가루"],["和食","héshí","일식"],["时令","shílìng","제철"],["棋盘式","qípánshì","바둑판식"]],"tr":["이 가정식 볶음 요리는 만드는 법이 아주 간단해, 주재료 말고는 소금, 생추, 백설탕, 흑초와 후춧가루 약간, 이렇게 네 가지 양념만 쓰면 된다.","일본의 와쇼쿠 문화는 식재료의 계절성을 중시해, 철마다 그 계절에 가장 신선한 맛을 즐기는 것을 따진다.","오랫동안 불안한 상태에 있으면 몸이 스트레스 호르몬을 계속 분비해 소화와 면역 기능에 영향을 준다.","이 고성의 거리 배치는 지금도 당나라의 바둑판식 구조를 유지해, 고대 도시 계획을 연구하는 살아 있는 표본으로 여겨진다."],"ow":[[["家常","jiācháng","가정식"],["小炒","xiǎochǎo","볶음 요리"],["调料","tiáoliào","양념"],["生抽","shēngchōu","생추(연한 간장)"],["香醋","xiāngcù","흑초"],["胡椒粉","hújiāofěn","후춧가루"]],[["和食","héshí","일본 요리"],["季节性","jìjiéxìng","계절성"],["时令","shílìng","철"]],[["焦虑","jiāolǜ","불안"],["分泌","fēnmì","분비"],["激素","jīsù","호르몬"],["免疫","miǎnyì","면역"]],[["街巷","jiēxiàng","거리와 골목"],["棋盘式","qípánshì","바둑판식"],["格局","géjú","구조"],["标本","biāoběn","표본"]]]},{"o":["人们常说“饭后一支烟，赛过活神仙”，其实饭后吸烟对消化系统的危害比平时更大。","在南方潮湿的梅雨季节，衣物和食物都容易发霉，家家户户都会想办法除湿防潮。","这是这位中国厨师首次登上国际烹饪大赛的领奖台，他再次用一道创意川菜征服了评委。","章鱼的每条腕足上都有大量神经元，即便离开大脑的指挥，也能独立完成一些简单的动作。"],"a":2,"type":"자기모순","why":"“首次”(처음)라고 해 놓고 “再次”(다시)라고 해 앞뒤가 모순된다.","fix":"这是这位中国厨师首次登上国际烹饪大赛的领奖台，他用一道创意川菜征服了评委。","words":[["领奖台","lǐngjiǎngtái","시상대"],["征服","zhēngfú","정복하다"],["梅雨","méiyǔ","장마"],["发霉","fāméi","곰팡이 피다"],["章鱼","zhāngyú","문어"],["神经元","shénjīngyuán","뉴런"]],"tr":["사람들은 흔히 '밥 먹고 담배 한 대면 신선도 부럽지 않다'고 하지만, 사실 식후 흡연은 평소보다 소화계에 더 해롭다.","남방의 눅눅한 장마철에는 옷과 음식에 곰팡이가 쉽게 피어, 집집마다 습기를 없애고 막을 방법을 찾는다.","이번은 이 중국 요리사가 국제 요리 대회 시상대에 처음 오른 것으로, 그는 다시 한 번 창의적인 쓰촨 요리 하나로 심사위원을 사로잡았다.","문어의 다리마다 신경세포가 많아, 뇌의 지휘를 벗어나도 몇 가지 간단한 동작은 스스로 해낸다."],"ow":[[["赛过","sàiguò","~보다 낫다"],["活神仙","huó shénxiān","살아 있는 신선"],["吸烟","xīyān","흡연"],["消化系统","xiāohuà xìtǒng","소화계"]],[["潮湿","cháoshī","습하다"],["梅雨","méiyǔ","장마"],["发霉","fāméi","곰팡이가 피다"],["除湿","chúshī","제습"]],[["烹饪","pēngrèn","요리"],["领奖台","lǐngjiǎngtái","시상대"],["创意","chuàngyì","창의"],["征服","zhēngfú","정복하다"],["评委","píngwěi","심사위원"]],[["章鱼","zhāngyú","문어"],["腕足","wànzú","다리(완족)"],["神经元","shénjīngyuán","신경세포"],["指挥","zhǐhuī","지휘"]]]}],[{"o":["广式月饼的饼皮柔软油润，关键在于和面时加入了熬制好的转化糖浆。","这家社区食堂本着少油少盐、营养均衡为原则，为周边老人提供价格实惠的一日三餐。","多项研究表明，规律的有氧运动不仅能增强心肺功能，还有助于延缓大脑的衰老。","这座悬索桥的主跨长达一千七百米，建成时曾创下同类桥梁的世界纪录。"],"a":1,"type":"구식 혼합","why":"“本着……的原则”와 “以……为原则” 두 구조가 섞여 “本着……为原则”가 되었다.","fix":"这家社区食堂本着少油少盐、营养均衡的原则，为周边老人提供价格实惠的一日三餐。","words":[["本着","běnzhe","~에 입각하여"],["实惠","shíhuì","실속 있다"],["月饼","yuèbing","월병"],["转化糖浆","zhuǎnhuà tángjiāng","전화당 시럽"],["延缓","yánhuǎn","늦추다"],["悬索桥","xuánsuǒqiáo","현수교"]],"tr":["광둥식 월병의 겉피가 부드럽고 촉촉한 것은 반죽할 때 끓여 둔 전화당 시럽을 넣는 데 비결이 있다.","이 지역 식당은 기름과 소금을 줄이고 영양 균형을 맞춘다는 원칙에 따라 주변 노인들에게 값싼 하루 세 끼를 제공한다.","여러 연구에 따르면 규칙적인 유산소 운동은 심폐 기능을 키울 뿐 아니라 뇌의 노화를 늦추는 데도 도움이 된다.","이 현수교의 주경간은 1,700미터에 달해, 완공 당시 같은 종류 다리의 세계 기록을 세웠다."],"ow":[[["月饼","yuèbing","월병"],["饼皮","bǐngpí","겉피"],["油润","yóurùn","윤기가 나다"],["转化糖浆","zhuǎnhuà tángjiāng","전화당 시럽"]],[["本着","běnzhe","~에 입각하여"],["均衡","jūnhéng","균형"],["实惠","shíhuì","실속 있다"]],[["有氧运动","yǒuyǎng yùndòng","유산소 운동"],["心肺","xīnfèi","심폐"],["延缓","yánhuǎn","늦추다"],["衰老","shuāilǎo","노화"]],[["悬索桥","xuánsuǒqiáo","현수교"],["主跨","zhǔkuà","주경간"],["纪录","jìlù","기록"]]]},{"o":["广东人素来把一碗慢火细煲的老火靓汤为餐桌上不可或缺的养生佳品。","临床观察发现，睡前适度泡脚能够促进下肢血液循环，帮助一些轻度失眠者更快地进入睡眠状态。","这位语言学家走访了几十个偏远村寨，记录下了多种即将消亡的少数民族语言。","这家企业把每年利润的一部分用于资助贫困地区的儿童，十多年来一直如此。"],"a":0,"type":"구식 혼합","why":"“把……视为……”와 “以……为……” 두 구조가 섞여 “把……为……”가 되었다.","fix":"广东人素来把一碗慢火细煲的老火靓汤视为餐桌上不可或缺的养生佳品。","words":[["煲","bāo","푹 고다"],["老火靓汤","lǎohuǒ liàngtāng","오래 고은 광둥식 탕"],["不可或缺","bù kě huò quē","없어서는 안 되다"],["泡脚","pàojiǎo","족욕"],["下肢","xiàzhī","하지"],["村寨","cūnzhài","마을"],["资助","zīzhù","경제적으로 돕다"]],"tr":["광둥 사람들은 예로부터 약한 불에 오래 고아 낸 국물 한 그릇을 식탁에 빠질 수 없는 보양식으로 여겨 왔다.","임상 관찰에 따르면 잠들기 전 적당히 족욕을 하면 다리의 혈액순환이 좋아져 가벼운 불면증이 있는 사람이 더 빨리 잠들게 돕는다.","이 언어학자는 외딴 마을 수십 곳을 찾아다니며 곧 사라질 여러 소수민족 언어를 기록했다.","이 기업은 해마다 이익의 일부를 가난한 지역 아이들을 돕는 데 써 왔고, 10여 년 동안 한결같았다."],"ow":[[["素来","sùlái","예로부터"],["细煲","xì bāo","오래 고다"],["老火靓汤","lǎohuǒ liàngtāng","오래 곤 보양탕"],["养生","yǎngshēng","양생"]],[["临床","línchuáng","임상"],["泡脚","pàojiǎo","족욕"],["血液循环","xuèyè xúnhuán","혈액순환"],["失眠","shīmián","불면"]],[["语言学家","yǔyánxuéjiā","언어학자"],["村寨","cūnzhài","마을"],["消亡","xiāowáng","소멸하다"],["少数民族","shǎoshù mínzú","소수민족"]],[["利润","lìrùn","이윤"],["资助","zīzhù","돕다"],["贫困","pínkùn","빈곤"]]]},{"o":["这种生活在雨林中的箭毒蛙体色鲜艳，以此警告捕食者自己身上带有剧毒。","随着电子阅读的普及，实体书店纷纷转型，在卖书之外增加了咖啡、展览和讲座等多种业态。","研究显示，咀嚼口香糖能在一定程度上缓解紧张情绪，这也是一些运动员在比赛时嚼口香糖的原因之一。","很多人吃完火锅后第二天容易口干舌燥的原因，是因为火锅汤底中含有大量的油脂和辛辣调料。"],"a":3,"type":"구식 혼합","why":"“……的原因是……”와 “……是因为……” 두 구조가 섞였다.","fix":"很多人吃完火锅后第二天容易口干舌燥的原因，是火锅汤底中含有大量的油脂和辛辣调料。","words":[["口干舌燥","kǒu gān shé zào","입이 바싹 마르다"],["汤底","tāngdǐ","육수"],["油脂","yóuzhī","유지"],["箭毒蛙","jiàndúwā","독화살개구리"],["业态","yètài","사업 형태"],["咀嚼","jǔjué","씹다"]],"tr":["열대우림에 사는 이 독화살개구리는 몸빛이 화려한데, 이것으로 포식자에게 자기 몸에 맹독이 있다고 경고한다.","전자책이 널리 퍼지면서 오프라인 서점들이 잇달아 변신해, 책 판매 말고도 커피, 전시, 강연 등 여러 업종을 더했다.","연구에 따르면 껌을 씹으면 긴장을 어느 정도 풀 수 있는데, 이것이 일부 선수들이 경기 중 껌을 씹는 이유 가운데 하나다.","많은 사람이 훠궈를 먹은 다음 날 입과 혀가 바싹 마르는 것은 훠궈 국물에 기름과 매운 양념이 많이 들어 있기 때문이다."],"ow":[[["雨林","yǔlín","우림"],["箭毒蛙","jiàndúwā","독화살개구리"],["鲜艳","xiānyàn","선명하고 화려하다"],["捕食者","bǔshízhě","포식자"],["剧毒","jùdú","맹독"]],[["普及","pǔjí","보급"],["实体书店","shítǐ shūdiàn","오프라인 서점"],["转型","zhuǎnxíng","전환하다"],["业态","yètài","업종 형태"]],[["咀嚼","jǔjué","씹다"],["口香糖","kǒuxiāngtáng","껌"],["缓解","huǎnjiě","완화하다"]],[["火锅","huǒguō","훠궈"],["口干舌燥","kǒu gān shé zào","입이 마르고 혀가 타다"],["汤底","tāngdǐ","국물 베이스"],["辛辣","xīnlà","맵다"]]]},{"o":["清代宫廷每到夏季便从冰窖中取出冬天储存的天然冰块，用来消暑和保存食物。","这位外科医生在长达十个小时的手术中始终保持着高度专注，最终成功地为患者摘除了肿瘤。","在不少营养学家看来，他们认为所谓“超级食物”的功效被商家过度夸大了。","一些城市在老旧小区改造中增设了口袋公园，让居民在家门口就能享受到绿色空间。"],"a":2,"type":"구식 혼합","why":"“在……看来”와 “……认为” 두 구조가 섞였다.","fix":"在不少营养学家看来，所谓“超级食物”的功效被商家过度夸大了。","words":[["夸大","kuādà","과장하다"],["冰窖","bīngjiào","빙고"],["消暑","xiāoshǔ","더위를 식히다"],["外科","wàikē","외과"],["肿瘤","zhǒngliú","종양"],["口袋公园","kǒudai gōngyuán","소공원"]],"tr":["청나라 궁정은 여름마다 빙고에서 겨울에 저장해 둔 천연 얼음을 꺼내 더위를 식히고 음식을 보관했다.","이 외과 의사는 열 시간에 걸친 수술 내내 고도의 집중력을 유지해 마침내 환자의 종양을 성공적으로 떼어 냈다.","많은 영양학자는 이른바 '슈퍼푸드'의 효능이 상인들에 의해 지나치게 부풀려졌다고 본다.","일부 도시는 노후 단지를 고치면서 자투리 공원을 더 만들어, 주민들이 집 앞에서 녹지를 누릴 수 있게 했다."],"ow":[[["宫廷","gōngtíng","궁정"],["冰窖","bīngjiào","빙고(얼음 창고)"],["消暑","xiāoshǔ","더위를 식히다"]],[["外科","wàikē","외과"],["专注","zhuānzhù","집중하다"],["摘除","zhāichú","떼어 내다"],["肿瘤","zhǒngliú","종양"]],[["营养学家","yíngyǎngxuéjiā","영양학자"],["超级食物","chāojí shíwù","슈퍼푸드"],["功效","gōngxiào","효능"],["夸大","kuādà","과장하다"]],[["老旧小区","lǎojiù xiǎoqū","노후 단지"],["增设","zēngshè","증설하다"],["口袋公园","kǒudai gōngyuán","자투리 공원"]]]},{"o":["相传早在汉代，张骞出使西域时就带回了葡萄、石榴、核桃等作物，极大地丰富了中原人的餐桌。","肥胖不仅仅是体重超标的问题，它还与高血压、糖尿病等多种慢性病的发生密切相关。","在长达半个世纪的潜心研究中，使这位农学家培育出了数十个适合高寒山区种植的马铃薯新品种。","这座城市把废弃的铁路改造成了一条绵延十几公里的空中步道，深受市民喜爱。"],"a":2,"type":"주어 결여","why":"“在……中，使……” 때문에 “农学家”가 “使”의 목적어가 되어 주어가 없다.","fix":"在长达半个世纪的潜心研究中，这位农学家培育出了数十个适合高寒山区种植的马铃薯新品种。","words":[["潜心","qiánxīn","몰두하다"],["培育","péiyù","육성하다"],["高寒","gāohán","높고 추운"],["马铃薯","mǎlíngshǔ","감자"],["张骞","Zhāng Qiān","장건"],["西域","Xīyù","서역"],["绵延","miányán","길게 이어지다"]],"tr":["전하기로는 일찍이 한나라 때 장건이 서역에 사신으로 갔다가 포도, 석류, 호두 같은 작물을 가져와 중원 사람들의 식탁을 크게 풍성하게 했다고 한다.","비만은 체중이 기준을 넘는 문제만이 아니라 고혈압, 당뇨병 같은 여러 만성병의 발생과도 밀접하게 관련된다.","반세기에 걸친 연구 끝에 이 농학자는 고한 산간 지대에 맞는 감자 신품종 수십 가지를 길러 냈다.","이 도시는 버려진 철도를 십여 킬로미터 이어지는 공중 산책로로 바꿔 시민들에게 사랑받고 있다."],"ow":[[["张骞","Zhāng Qiān","장건"],["出使","chūshǐ","사신으로 가다"],["西域","Xīyù","서역"],["石榴","shíliu","석류"],["中原","Zhōngyuán","중원"]],[["肥胖","féipàng","비만"],["超标","chāobiāo","기준을 넘다"],["糖尿病","tángniàobìng","당뇨병"],["慢性病","mànxìngbìng","만성병"]],[["潜心","qiánxīn","몰두하다"],["农学家","nóngxuéjiā","농학자"],["培育","péiyù","길러 내다"],["马铃薯","mǎlíngshǔ","감자"]],[["废弃","fèiqì","버리다"],["绵延","miányán","길게 이어지다"],["步道","bùdào","산책로"]]]},{"o":["人体的生物钟主要受光线调节，因此早晨起床后拉开窗帘晒晒太阳，有助于让人迅速清醒。","这家老字号今年春天推出的低糖青团一上市便受到了年轻消费者的热捧，销售量十分畅销。","这位老人年近九旬依然耳聪目明，他说自己长寿的秘诀就是心态平和、饮食清淡。","黑洞的引力极其强大，就连光都无法从中逃逸，因此人类只能通过观测其周围的物质间接探测它。"],"a":1,"type":"주어–술어","why":"잘 팔리는(畅销) 것은 상품이지 “销售量”이 아니어서 주어와 술어가 맞지 않는다.","fix":"这家老字号今年春天推出的低糖青团一上市便受到了年轻消费者的热捧，销售量十分可观。","words":[["青团","qīngtuán","칭퇀(쑥떡)"],["热捧","rèpěng","열렬히 환영하다"],["畅销","chàngxiāo","잘 팔리다"],["可观","kěguān","상당하다"],["耳聪目明","ěr cōng mù míng","귀와 눈이 밝다"],["逃逸","táoyì","빠져나가다"]],"tr":["사람의 생체 시계는 주로 빛의 영향을 받으므로, 아침에 일어나 커튼을 젖히고 햇볕을 쬐면 빨리 정신이 든다.","이 노포가 올봄 내놓은 저당 칭퇀은 나오자마자 젊은 소비자들의 큰 인기를 얻어 판매량이 아주 좋았다.","이 노인은 아흔 가까운 나이에도 귀와 눈이 밝은데, 장수 비결은 평온한 마음과 담백한 식사라고 한다.","블랙홀은 중력이 매우 강해 빛조차 빠져나올 수 없어서, 인류는 그 주변 물질을 관측해 간접적으로 찾아낼 수밖에 없다."],"ow":[[["生物钟","shēngwùzhōng","생체 시계"],["调节","tiáojié","조절"],["窗帘","chuānglián","커튼"]],[["老字号","lǎozìhao","노포"],["青团","qīngtuán","칭퇀(쑥떡)"],["热捧","rèpěng","열렬히 지지하다"],["畅销","chàngxiāo","잘 팔리다"]],[["年近九旬","nián jìn jiǔ xún","아흔에 가깝다"],["耳聪目明","ěr cōng mù míng","귀와 눈이 밝다"],["秘诀","mìjué","비결"],["清淡","qīngdàn","담백하다"]],[["黑洞","hēidòng","블랙홀"],["逃逸","táoyì","빠져나가다"],["观测","guāncè","관측"],["探测","tàncè","탐지하다"]]]},{"o":["这款软件可以根据用户输入的身高、体重和运动量，自动计算出每日所需的热量。","长时间佩戴隐形眼镜会导致角膜缺氧，因此专家建议每天佩戴时间不宜超过八小时。","这座边境小城由于地处多民族交汇之处，饮食文化呈现出鲜明的多元特征。","早在两千多年前的西汉，就我国先民已经开始用石磨把小麦磨成面粉了。"],"a":3,"type":"부사 위치","why":"부사 “就”는 주어 “我国先民” 뒤, 동사 앞에 와야 한다.","fix":"早在两千多年前的西汉，我国先民就已经开始用石磨把小麦磨成面粉了。","words":[["西汉","Xī Hàn","서한"],["石磨","shímò","맷돌"],["热量","rèliàng","열량"],["隐形眼镜","yǐnxíng yǎnjìng","콘택트렌즈"],["角膜","jiǎomó","각막"],["交汇","jiāohuì","합류하다"],["多元","duōyuán","다원적"]],"tr":["이 앱은 사용자가 입력한 키, 몸무게, 운동량으로 하루 필요한 열량을 자동으로 계산해 준다.","콘택트렌즈를 오래 끼면 각막에 산소가 부족해지므로, 전문가들은 하루 착용 시간이 여덟 시간을 넘지 않는 게 좋다고 권한다.","이 국경의 작은 도시는 여러 민족이 만나는 곳에 있어 음식 문화가 뚜렷하게 다채롭다.","일찍이 2천여 년 전 서한 때 우리나라 사람들은 이미 맷돌로 밀을 갈아 밀가루를 만들기 시작했다."],"ow":[[["软件","ruǎnjiàn","소프트웨어"],["热量","rèliàng","열량"]],[["隐形眼镜","yǐnxíng yǎnjìng","콘택트렌즈"],["角膜","jiǎomó","각막"],["缺氧","quēyǎng","산소 부족"],["不宜","bùyí","좋지 않다"]],[["边境","biānjìng","국경"],["交汇","jiāohuì","만나다"],["多元","duōyuán","다원적"]],[["西汉","Xī Hàn","서한"],["先民","xiānmín","옛사람"],["石磨","shímò","맷돌"],["面粉","miànfěn","밀가루"]]]},{"o":["既然医生已经明确诊断你是由于长期饮食不规律导致的胃炎，你才更应该按时吃饭，戒掉吃宵夜的习惯。","这项发明的灵感来源于荷叶表面的微观结构，它能让水珠自然滚落并带走表面的灰尘。","在海拔四千米以上的高原地区，即使是在盛夏，夜间气温也常常降到零度以下。","这位民间艺人用一把铜勺和一锅糖稀，就能在石板上勾勒出惟妙惟肖的龙凤图案。"],"a":0,"type":"짝 오류","why":"“既然”은 “就”와 짝을 이룬다. “既然……才”는 짝이 틀렸다.","fix":"既然医生已经明确诊断你是由于长期饮食不规律导致的胃炎，你就更应该按时吃饭，戒掉吃宵夜的习惯。","words":[["诊断","zhěnduàn","진단하다"],["宵夜","xiāoyè","야식"],["灵感","línggǎn","영감"],["糖稀","tángxī","물엿"],["勾勒","gōulè","윤곽을 그리다"],["惟妙惟肖","wéi miào wéi xiào","실물처럼 생생하다"]],"tr":["의사가 오랜 불규칙한 식사로 생긴 위염이라고 분명히 진단했으니, 너는 더욱 제때 밥을 먹고 야식 습관을 끊어야 한다.","이 발명의 영감은 연잎 표면의 미세 구조에서 왔는데, 물방울이 저절로 굴러떨어지며 표면 먼지를 쓸어 가게 한다.","해발 4천 미터가 넘는 고원에서는 한여름에도 밤 기온이 영하로 떨어지는 일이 잦다.","이 민간 예인은 구리 국자 하나와 조청 한 솥만으로 돌판 위에 생생한 용과 봉황 그림을 그려 낸다."],"ow":[[["诊断","zhěnduàn","진단하다"],["胃炎","wèiyán","위염"],["宵夜","xiāoyè","야식"]],[["灵感","línggǎn","영감"],["荷叶","héyè","연잎"],["微观","wēiguān","미시적"],["灰尘","huīchén","먼지"]],[["海拔","hǎibá","해발"],["盛夏","shèngxià","한여름"]],[["艺人","yìrén","예인"],["铜勺","tóngsháo","구리 국자"],["糖稀","tángxī","조청"],["勾勒","gōulè","윤곽을 그리다"],["惟妙惟肖","wéi miào wéi xiào","아주 생생하다"]]]},{"o":["对于正处在快速生长期的青少年来说，适量摄入优质蛋白质是保证骨骼和肌肉发育的关键。","这家百年面馆每天清晨五点便开始熬汤，一锅骨汤要用近五十斤以上的猪骨和鸡架慢火熬制六个小时。","这位摄影师用延时拍摄的方式，记录下了一朵昙花从含苞到凋谢的全过程。","地中海饮食以橄榄油、全谷物、蔬果和鱼类为主，被许多研究证明有助于降低心血管疾病的风险。"],"a":1,"type":"어림수 중복","why":"“近”(조금 못 미침)과 “以上”(넘음)이 함께 쓰여 겹치고 모순된다.","fix":"这家百年面馆每天清晨五点便开始熬汤，一锅骨汤要用近五十斤猪骨和鸡架慢火熬制六个小时。","words":[["鸡架","jījià","닭뼈"],["慢火","mànhuǒ","약한 불"],["蛋白质","dànbáizhì","단백질"],["延时拍摄","yánshí pāishè","타임랩스 촬영"],["昙花","tánhuā","월하미인"],["含苞","hánbāo","봉오리를 머금다"],["凋谢","diāoxiè","시들다"],["橄榄油","gǎnlǎnyóu","올리브유"]],"tr":["한창 빨리 자라는 청소년에게는 양질의 단백질을 알맞게 섭취하는 것이 뼈와 근육 발달을 보장하는 열쇠다.","이 백 년 된 국숫집은 매일 새벽 다섯 시면 육수를 끓이기 시작하는데, 뼈 육수 한 솥에 돼지뼈와 닭뼈를 쉰 근 가까이 넣고 약한 불로 여섯 시간을 곤다.","이 사진가는 저속 촬영으로 월하미인 한 송이가 봉오리부터 질 때까지의 전 과정을 담았다.","지중해식 식단은 올리브유, 통곡물, 채소·과일, 생선을 중심으로 하며, 여러 연구에서 심혈관 질환 위험을 낮추는 데 도움이 된다고 밝혀졌다."],"ow":[[["摄入","shèrù","섭취"],["蛋白质","dànbáizhì","단백질"],["骨骼","gǔgé","뼈"],["肌肉","jīròu","근육"]],[["面馆","miànguǎn","국숫집"],["熬汤","áotāng","육수를 끓이다"],["鸡架","jījià","닭뼈"],["慢火","mànhuǒ","약한 불"]],[["摄影师","shèyǐngshī","사진가"],["延时拍摄","yánshí pāishè","저속 촬영"],["昙花","tánhuā","월하미인"],["含苞","hánbāo","꽃봉오리를 머금다"],["凋谢","diāoxiè","시들다"]],[["地中海","Dìzhōnghǎi","지중해"],["橄榄油","gǎnlǎnyóu","올리브유"],["全谷物","quángǔwù","통곡물"],["心血管","xīnxuèguǎn","심혈관"]]]},{"o":["宋代以后，随着棉花种植的推广，棉布逐渐取代麻布，成为普通百姓制作衣物的主要材料。","那些在逆境中依然保持乐观的人，往往更善于从失败中发现转机。","这家博物馆收藏的一批明代宫廷食谱，详细记载了数百道菜肴的用料与做法，具有很高的史料价值。","一个人晚餐吃得是否清淡适量，在很大程度上决定了他当晚能睡个好觉。"],"a":3,"type":"양면–한면","why":"앞은 “是否”(두 면)인데 뒤는 “能睡个好觉”(한 면)이라 맞지 않는다.","fix":"一个人晚餐吃得是否清淡适量，在很大程度上决定了他当晚能否睡个好觉。","words":[["清淡","qīngdàn","담백하다"],["棉花","miánhua","목화"],["麻布","mábù","삼베"],["逆境","nìjìng","역경"],["转机","zhuǎnjī","반전의 기회"],["史料","shǐliào","사료"]],"tr":["송나라 이후 목화 재배가 퍼지면서 무명이 점차 삼베를 대신해 서민들이 옷을 짓는 주된 재료가 되었다.","역경 속에서도 낙관을 잃지 않는 사람은 대개 실패에서 전환점을 더 잘 찾아낸다.","이 박물관이 소장한 명나라 궁정 요리책은 요리 수백 가지의 재료와 조리법을 자세히 적어 사료적 가치가 매우 높다.","저녁을 담백하고 알맞게 먹었는지가 그날 밤 잠을 잘 잘 수 있는지를 상당 부분 결정한다."],"ow":[[["棉花","miánhua","목화"],["推广","tuīguǎng","보급하다"],["棉布","miánbù","면포"],["麻布","mábù","삼베"],["百姓","bǎixìng","백성"]],[["逆境","nìjìng","역경"],["乐观","lèguān","낙관"],["转机","zhuǎnjī","전환점"]],[["收藏","shōucáng","소장하다"],["宫廷","gōngtíng","궁정"],["菜肴","càiyáo","요리"],["史料","shǐliào","사료"]],[["清淡","qīngdàn","담백하다"],["适量","shìliàng","적당량"]]]}]];
